// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Moda, giyim tarihi ve tekstil terimleri (orta).
const ozCulture9Orta = <(String, String, List<String>, String)>[
  ('Keten, kenevir ve jüt liflerinin ortak özelliği hangisidir?', 'Bitki gövdesinden elde edilen sap lifleri olmaları', ['Hayvanların tüylerinden ya da salgılarından elde edilmeleri', 'Hayvansal protein içermeleri', 'Petrolden üretilmeleri'], 'Bu üç lif, bitkinin gövdesinde kabuğun altındaki lif demetlerinden elde edilir; bu yüzden sap (gövde) lifi diye anılır.'),
  ('Bir köylü hasat ettiği keten saplarını, lifleri kolayca ayırabilmek için birkaç hafta bir göletin suyunda bekletiyor. Uyguladığı bu işlemin adı nedir?', 'Havuzlama', ['Merserizasyon', 'Kardelama', 'Çırçırlama'], 'Havuzlama (İng. retting), mikroorganizmaların pektini ayrıştırmasıyla liflerin saptan kolayca ayrılmasını sağlar.'),
  ('Bitkisel lifler kaynaklandıkları bölüme göre tohum, sap ve yaprak lifleri diye ayrılır. Hangisi bir yaprak lifidir?', 'Sisal', ['Pamuk', 'Keten', 'Kenevir'], 'Sisal, agav türü bir bitkinin kalın yapraklarından elde edilir; pamuk tohum lifi, keten ve kenevir sap lifidir.'),
  ('Yaz aylarında keten gömleklerin serin tutmasının başlıca nedeni hangisidir?', 'Nemi çabuk emip ısıyı iyi iletmesi', ['Esneyerek bedene sıkıca oturması', 'Yüzeyinin havlı ve kabarık olup hava hapsetmesi', 'Su geçirmez bir kaplama taşıması'], 'Keten lifi teri çabuk emip hızla buharlaştırır ve ısıyı iyi iletir; bu yüzden sıcak havada serinlik hissi verir.'),
  ('Bir kişi keten pantolonunun kısa bir oturuştan sonra bile kırış kırış olduğunu fark ediyor. Bunun liften kaynaklanan nedeni nedir?', 'Liflerin esneyip eski biçimine dönememesi', ['Liflerin çok kısa, kıvırcık ve pullu bir yapıda olması', 'Lifin suyu hiç emmemesi', 'Lifin sentetik bir kaplama içermesi'], 'Keten lifi sert ve az esnektir; büküldüğünde eski biçimine kolay dönemediği için kumaş çabuk buruşur.'),
  ('Pamuk ticaretinde bir partinin \'ekstra uzun stapel\' olarak sınıflandırılması neyi anlatır?', 'Liflerin ortalama uzunluğunun çok yüksek olduğunu', ['Pamuğun sertifikalı organik tarımla yetiştirildiğini', 'Liflerin yapay olarak boyandığını', 'Balyaların normalden ağır olduğunu'], 'Stapel, lif uzunluğunu anlatır; uzun lifler daha ince, sağlam ve parlak iplik eğrilmesini sağlar, bu yüzden değerlidir.'),
  ('İpek lifini oluşturan temel protein hangisidir?', 'Fibroin', ['Keratin', 'Kolajen', 'Kazein'], 'İpek, ipekböceği tırtılının salgıladığı fibroin proteininden oluşur; sırasin adlı yapıştırıcı protein onu kaplar.'),
  ('Bir mağazada \'angora\' etiketli bir kazak satılıyor. Bu kazağın lifi hangi hayvandan elde edilmiştir?', 'Ankara tavşanından', ['Ankara keçisinden', 'Ankara kedisinden', 'Merinos koyununun kuzusundan'], 'Angora yünü Ankara tavşanının tüyüdür; Ankara keçisinin lifi ise tiftik (mohair) adıyla satılır.'),
  ('Doğal lifler arasında kesintisiz, yüzlerce metre uzunluğunda filament olarak elde edilebilen tek lif hangisidir?', 'İpek', ['Pamuk', 'Yün', 'Keten'], 'Bir kozadan çözülen ipek lifi yüzlerce metre uzunlukta olabilir; diğer doğal lifler ise birkaç santimetrelik kesikli liflerdir.'),
  ('Kalın bir yün kazağın soğukta iyi sıcak tutmasının başlıca nedeni hangisidir?', 'Kıvrımlı liflerin arasında durgun hava hapsetmesi', ['Lifin içinde vücut ısısını artıran bir madde bulunması', 'Rüzgârı tümüyle geçirmemesi', 'Güneş ışığını yansıtması'], 'Yün lifleri doğal olarak kıvrımlıdır; aralarında hapsolan durgun hava iyi bir ısı yalıtkanıdır.'),
  ('Bir kozmetik firması, ham yünün yıkanmasından elde edilen doğal bir yağı nemlendirici krem üretiminde kullanmak istiyor. Firmanın kullanacağı madde hangisidir?', 'Lanolin', ['Gliserin', 'Parafin', 'Lesitin'], 'Lanolin koyunun derisindeki yağ bezlerinden salgılanan \'yün yağı\'dır; yün yıkamada elde edilir.'),
  ('Bir giysi etiketinde \'yeni yün\' (İng. virgin wool) ifadesinin bulunması ne anlama gelir?', 'Daha önce hiç işlenmemiş yünden yapıldığına', ['Yünün hiç boyanmadığına', 'Yünün yalnız ilk kırkımdaki kuzulardan alındığına', 'Yünün hiçbir sentetik ya da bitkisel lifle karıştırılmadığına'], 'Yeni yün, daha önce kumaş ya da ürün olarak işlenmemiş yündür; geri dönüştürülmüş yünden ayırmak için kullanılır.'),
  ('İkinci Dünya Savaşı yıllarında ABD\'de kadın çoraplarının bulunmaz hâle gelmesinin başlıca nedeni neydi?', 'Naylonun paraşüt gibi askerî üretime ayrılması', ['Pamuk tarlalarının uzun süren kuraklıkla kuruması', 'İpek ithalatının yeniden başlaması', 'Çorap giymenin yasakla engellenmesi'], 'Savaş sırasında naylon paraşüt, halat ve çadır gibi askerî ihtiyaçlara yönlendirildi; naylon çoraplar karaborsada çok pahalıya satıldı.'),
  ('Bir koruyucu giysi üreticisi itfaiyeciler için alev almaya ve yırtılmaya çok dayanıklı bir lif arıyor. Hangi lif grubunu seçmelidir?', 'Aramid', ['Akrilik', 'Viskon', 'Modal'], 'Aramid lifleri (ör. Kevlar, Nomex) çok yüksek dayanım ve alev direnciyle koruyucu giysilerde kullanılır.'),
  ('Yüzde yüz polyester bir bluzu pamuk ayarındaki çok sıcak ütüyle ütüleyen kişinin karşılaşması en olası sorun hangisidir?', 'Kumaşın erimesi ya da parlayıp sertleşmesi', ['Kumaşın renginin koyulaşması', 'Kumaşın keçeleşip kalınlaşması', 'Kumaşın tümüyle küçülüp boyunun yarısına inmesi'], 'Polyester termoplastik bir liftir; yüksek sıcaklıkta yumuşar ve erir, bu yüzden düşük ısıda ütülenmelidir.'),
  ('Koşu sırasında giyilen polyester tişörtün aynı kalınlıktaki pamuklu tişörtten daha çabuk kurumasının nedeni nedir?', 'Polyester lifinin suyu çok az emmesi', ['Polyesterin daha seyrek dokunması', 'Pamuğun suyu itmesi', 'Polyesterin vücut ısısını yükseltmesi'], 'Polyester hidrofobiktir; nemi lifin içine almaz, nem yüzeyde kalıp çabuk buharlaşır. Pamuk ise suyu lifin içine çeker.'),
  ('Anadolu\'da yünü elde eğirmek için kullanılan, ucunda kanatlar ya da ağırlık bulunan bir milden oluşan basit araç hangisidir?', 'Kirmen', ['Mekik', 'Dokuma tarağı', 'Gergef'], 'Kirmen, döndürülerek yünü büken ve oluşan ipliği gövdesine saran geleneksel bir eğirme aracıdır.'),
  ('Pamuk ipliğinde \'penye\' ile \'karde\' arasındaki fark hangi işlemden kaynaklanır?', 'Kısa liflerin taranıp ayıklanmasından', ['Penyenin yalnız yün liflerinden yapılmasından', 'Kardenin iki kez boyanmasından', 'Penyenin hiç büküm almamasından'], 'Penye iplikte lifler ek bir tarama işlemiyle kısa liflerden arındırılır; iplik daha düzgün, parlak ve yumuşak olur.'),
  ('İpliklerde büküm yönünü belirtmek için hangi iki harf kullanılır?', 'S ve Z', ['L ve R harfleri', 'A ve B', 'X ve Y'], 'İplik dik tutulduğunda lifler S harfinin orta çizgisi gibi eğiliyorsa S büküm, Z harfi gibi eğiliyorsa Z büküm denir.'),
  ('İki ya da daha çok tek kat ipliğin birbiri etrafında bükülmesiyle elde edilen daha sağlam ipliğe ne ad verilir?', 'Katlı iplik', ['Filament iplik', 'Fitil', 'Tarak bandı'], 'Tek kat iplikler birlikte bükülerek katlı (çok katlı) iplik yapılır; dikiş ipliklerinin çoğu katlıdır.'),
  ('Rotor (open-end) iplikçiliğinin geleneksel halka iplikçiliğine göre başlıca üstünlüğü hangisidir?', 'Üretim hızının çok daha yüksek olması', ['Daha ince, parlak ve sağlam iplik vermesi', 'İpek lifine uygun olması', 'Hiç büküm gerektirmemesi'], 'Rotor iplikçiliği çok hızlı ve ekonomiktir; ancak elde edilen iplik genellikle halka ipliğinden daha kaba ve daha az sağlamdır.'),
  ('Adı Fransızca \'tırtıl\' anlamına gelen, her yanından kısa tüyler çıkan kadifemsi fantezi iplik hangisidir?', 'Şönil', ['Bukle', 'Simli iplik', 'Floş'], 'Şönil (Fr. chenille) ipliğinin tüylü görünümü tırtıla benzetilmiştir; döşemelik ve kazaklarda kullanılır.'),
  ('Tekstilde \'tex\' birimi neyi ölçer?', '1000 metre ipliğin gram cinsinden ağırlığını', ['1 gram ipliğin metre cinsinden toplam uzunluğunu', 'İpliğin metredeki büküm sayısını', 'İpliğin kopma kuvvetini'], 'Tex doğrudan bir numara sistemidir: 1000 metre iplik kaç gram geliyorsa ipliğin numarası o kadar tex\'tir.'),
  ('Saten örgülü kumaşların ışıltılı ve kaygan görünmesinin nedeni hangisidir?', 'Uzun atlayan ipliklerin yüzeyi kaplaması', ['Kumaşın yüzeyine ince bir cila tabakası sürülmesi', 'Yalnız ipekten dokunabilmesi', 'Atkı ve çözgünün eşit sıklıkta olması'], 'Saten örgüde bağlantı noktaları seyrek ve dağınıktır; yüzeyde uzun süre kalan iplikler ışığı düzgün yansıtır.'),
  ('Saten bir gece elbisesinin bezayağı dokunmuş bir pamuklu gömleğe göre takılıp iplik çekmeye daha yatkın olması nasıl açıklanır?', 'Uzun atlayan ipliklerin yüzeyde serbest kalması', ['Saten ipliklerinin hiç büküm almadan kullanılması', 'Bezayağında hiç atkı bulunmaması', 'Satenin örme bir kumaş olması'], 'Satenin parlaklığını sağlayan uzun atlamalar aynı zamanda ipliklerin kolayca bir yere takılıp çekilmesine yol açar.'),
  ('1800\'lerin başında, delikli kartlarla her çözgü ipliğini ayrı ayrı kaldırarak çok karmaşık desenlerin dokunmasını sağlayan tezgâh mekanizmasını geliştiren Fransız kimdir?', 'Joseph Marie Jacquard', ['Richard Arkwright', 'James Hargreaves', 'Edmund Cartwright'], 'Jacquard mekanizması desen bilgisini delikli kartlarla tezgâha aktarıyordu; bu fikir daha sonra bilgisayarların ilk programlama fikirlerine de esin kaynağı oldu.'),
  ('Saydamlıkta şifona benzediği hâlde ondan farklı olarak sert ve dik durduğu için gelinlik eteklerinde hacim vermek amacıyla kullanılan kumaş hangisidir?', 'Organze', ['Saten', 'Kaşe kumaşı', 'Jarse'], 'Organze ince ama sert bükümlü ipliklerle dokunur; bu sertlik ona şifondan farklı olarak hacimli bir duruş kazandırır.'),
  ('Kadife kumaşın yumuşak, tüylü yüzeyi nasıl elde edilir?', 'Ek ipliklerin oluşturduğu ilmeklerin kesilmesiyle', ['Kumaş yüzeyinin zımparalanmasıyla', 'Yünün sıcak sabunlu suda ovularak keçeleştirilmesiyle', 'Kumaşa yapıştırıcıyla tüy serpilmesiyle'], 'Kadife, ek bir atkı ya da çözgü sisteminin oluşturduğu ilmeklerin kesilmesiyle elde edilen havlı bir dokumadır.'),
  ('Desenleri, atkıya katılan altın ya da gümüş renkli ek ipliklerle kabartma etkisi verecek biçimde dokunmuş ağır ve gösterişli kumaşa genel olarak ne ad verilir?', 'Brokar', ['Poplin', 'Flanel', 'Patiska'], 'Brokar, desenin ek atkı iplikleriyle dokunduğu süslü kumaşların genel adıdır; saray ve tören giysilerinde kullanılmıştır.'),
  ('Elde şişle örgüde bir sıra düz, bir sıra ters örülerek elde edilen, bir yüzünde V biçimli ilmekler görülen temel örgüye ne ad verilir?', 'Jarse örgü', ['Lastik örgü', 'Haraşo örgü', 'Saç örgü'], 'Jarse örgüde ön yüzde V\'ler, arka yüzde kavisler görülür; makinede örülen süprem de bu yapıdadır.'),
  ('Krem rengi kalın yünden yapılan, burgu ve saç örgüsü gibi kabartma desenleriyle bilinen balıkçı kazakları adını hangi adalardan alır?', 'İrlanda\'daki Aran Adaları', ['İskoçya\'daki Orkney Adaları', 'Galler\'deki Anglesey Adası', 'İngiltere\'deki Wight Adası'], 'Aran kazakları İrlanda\'nın batısındaki Aran Adaları\'yla özdeşleşmiştir; kabartma desenleri sıcak tutan kalın bir doku oluşturur.'),
  ('Bir karayolu mühendisi dolgu toprağı ile alttaki zeminin birbirine karışmasını önlemek ve suyu süzmek için katmanlar arasına bir malzeme sermek istiyor. Hangisini kullanmalıdır?', 'Geotekstil', ['Agrotekstil', 'Medikal tekstil', 'Ev tekstili'], 'Geotekstiller inşaat mühendisliğinde kullanılan teknik tekstillerdir; agrotekstiller ise tarımda kullanılır.'),
  ('Dağcılık montlarında kullanılan \'nefes alan\' su geçirmez zarların çalışma ilkesi hangisidir?', 'Gözeneklerin damladan küçük, buhar molekülünden büyük olması', ['Kumaşın yüzeyinin kalın bir mumla kaplanması', 'Zarın dışarıdaki suyu emip depolaması', 'Zarın vücut ısısıyla suyu buharlaştırması'], 'Bu zarlardaki milyarlarca mikro gözenek sıvı damlaların girmesine izin vermez, terden oluşan buharın ise dışarı çıkmasını sağlar.'),
  ('Bir iplik üreticisi pamuk ipliğine ipeğe yakın bir parlaklık ve daha iyi boya alımı kazandırmak istiyor. İpliği hangi işlemden geçirmelidir?', 'Merserizasyon', ['Sanforizasyon', 'Karbonizasyon', 'Kalandırlama işlemi'], 'İşlem adını 19. yüzyılda bu etkiyi bulan John Mercer\'den alır; merserize pamuk ipeğe yakın bir parlaklık kazanır.'),
  ('Etiketinde \'sanforlu\' yazan pamuklu bir pantolondan hangi özellik beklenir?', 'Yıkamada çok az çekmesi', ['Hiç ütü gerektirmemesi', 'Suyu tümüyle itmesi', 'Güneşte renginin solmaması'], 'Sanfor işleminde kumaş önceden mekanik olarak çektirilir; böylece sonradan yıkamada çekme oranı çok düşük kalır.'),
  ('Bir fabrika battaniye kumaşının yüzeyindeki lifleri ince çelik tellerle çekerek ona yumuşak ve tüylü bir yüzey kazandırmak istiyor. Uygulaması gereken işlem hangisidir?', 'Şardon', ['Merserize', 'Haşıl', 'Kalandır'], 'Şardon (tüylendirme) işlemi flanel, polar ve battaniye gibi kumaşlara yumuşak, sıcak tutan bir yüzey kazandırır.'),
  ('Bir terbiye işletmesi pamuklu bir kumaşın yüzeyini ısıtılmış ağır silindirler arasından geçirerek düzleştirmek ve parlatmak istiyor. Bu işlemin adı nedir?', 'Kalandırlama', ['Şardonlama', 'Merserizasyon', 'Ağartma'], 'Kalandır makinesi ütüye benzer biçimde ısı ve basınç uygulayarak kumaş yüzeyini düzleştirir, parlaklık ya da kabartma deseni verebilir.'),
  ('Bir üretici boyanmış bir kumaşa son aşamada buruşmazlık ve su iticilik kazandırmak istiyor. Uygulanacak bu son işlemlerin genel adı nedir?', 'Apre', ['Haşıl', 'Çözgü', 'Kirkit'], 'Apre (bitim işlemi), boyama ve baskıdan sonra kumaşın tutumunu ve kullanım özelliklerini düzenleyen işlemlerin toplu adıdır.'),
  ('Kot pantolonlara aşınmış görünüm vermek için uygulanan kumlama işleminin Türkiye dâhil pek çok ülkede yasaklanmasının başlıca nedeni nedir?', 'İşçilerde silikozis hastalığına yol açması', ['Kumaşın tümüyle yırtılmasına yol açması', 'Boyanın denize karışıp kirlilik yaratması', 'Kot pantolonları aşırı pahalı hâle getirmesi'], 'Kumlamada solunan kristal silika tozu akciğerlerde kalıcı hasar ve silikozise yol açar; Türkiye bu işlemi 2009\'da yasaklamıştır.'),
  ('Kumaşın boyanmadan önce katlanıp büzülerek, bağlanarak ya da dikilerek sıkıştırılmasıyla desen oluşturulan geleneksel Japon tekniği hangisidir?', 'Shibori', ['Origami', 'Sashiko', 'Kintsugi'], 'Shibori\'de sıkıştırılan bölgeler boyayı almaz; böylece kumaşta dalga, halka ve benek gibi desenler oluşur. Sashiko ise bir dikiş tekniğidir.'),
  ('Desenin, kumaş dokunmadan önce ipliklerin belli bölümlerinin bağlanıp boyanmasıyla hazırlandığı ve dokuma sırasında ortaya çıktığı teknik hangisidir?', 'İkat', ['Serigrafi', 'Batik baskı', 'Devore baskı'], 'İkatta boyama dokumadan önce ipliğe uygulanır; ipliklerin tezgâhta küçük kaymaları desen kenarlarına tipik bulanık görünümü verir.'),
  ('Kalıp ya da elek hazırlamadan, bilgisayardaki görseli doğrudan kumaşa aktarabildiği için az adetli üretimlerde tercih edilen baskı yöntemi hangisidir?', 'Dijital baskı', ['Rotasyon elek baskısı', 'Tahta kalıpla blok baskı', 'Düz şablonlu serigrafi'], 'Dijital baskıda kalıp maliyeti yoktur; her parça farklı desende basılabilir, bu da küçük partileri ekonomik kılar.'),
  ('Bir doğal boyacı kökboyayla boyadığı yünün rengi ilk yıkamada akınca, bir dahaki sefere yünü önce şaplı suda kaynatıyor. Şabın burada üstlendiği göreve göre ait olduğu madde grubu hangisidir?', 'Mordan', ['Haşıl', 'Apre', 'Pigment'], 'Mordanlar boya ile lif arasında köprü kurar; Anadolu\'daki geleneksel kök boyacılıkta en çok şap kullanılmıştır.'),
  ('Kot kumaşının yıprandıkça yer yer beyazlaşmasının temel nedeni hangisidir?', 'İndigonun ipliğin yalnız dışını boyaması', ['Kumaşın güneşte ağarmaya çok yatkın olması', 'İndigonun pamukla hiç bağ kurmaması', 'Atkı ipliklerinin hiç boyanmamış olması'], 'İndigo çözgü ipliğine katman katman ve yüzeysel tutunur; ipliğin özü beyaz kalır. Aşındıkça beyaz öz görünür hâle gelir.'),
  ('Kökeni İskoçya\'ya dayanan ve bir Galler Prensi\'nin giymesiyle ünlenip onun unvanıyla anılan, küçük ve büyük karelerin iç içe geçtiği klasik takım elbise deseni hangisidir?', 'Prens dö gal', ['Balıksırtı deseni', 'Pötikare', 'Kazayağı'], 'Prens dö gal deseni Glen check olarak da bilinir; Galler Prensi unvanını taşıyan İngiliz veliahtlarının giymesiyle ün kazanmıştır.'),
  ('Lacivert ya da gri takım kumaşında, terzinin tebeşiriyle çizilmiş gibi kenarları hafif bulanık açık renk çizgilerden oluşan desene ne ad verilir?', 'Tebeşir çizgili', ['Pötikare', 'Kazayağı', 'Balıksırtı dokuma'], 'Tebeşir çizgisi, iğne çizgisine (pinstripe) göre daha kalın ve yumuşak kenarlı çizgiler içerir; klasik iş takımlarında sık görülür.'),
  ('Kumaş kenarına seyrek adımlı bir dikiş atıldıktan sonra iplik çekilerek elde edilen sık ve düzensiz kıvrımlara ne ad verilir?', 'Büzgü', ['Pens', 'Nervür', 'Kup'], 'Büzgüde kumaş ipliğin çekilmesiyle toplanır; kıvrımlar pilideki gibi ütülü ve düzenli değildir.'),
  ('Pens kullanmadan bir elbiseyi bedene oturtmak isteyen terzi, omuzdan ya da koltuk altından bele dikey inen biçimlendirme dikişleri kullanıyor. Bu dikişlerin adı nedir?', 'Prenses dikişi', ['Reglan dikişi', 'Fransız dikişi', 'Teyel dikişi'], 'Prenses (kup) dikişleri giysiyi pensler olmadan vücuda oturtur; bu kesim özellikle elbise ve ceketlerde zarif bir siluet verir.'),
  ('Dokuma bir kumaşın atkı ve çözgü ipliklerine 45 derece açıyla kesilmesi kumaşa hangi özelliği kazandırır?', 'Esneyip vücuda yumuşakça oturan bir döküm', ['Hiç kırışmayan sert bir yüzey', 'Su geçirmez bir yapı', 'Daha koyu ve canlı bir renk'], 'Verev kesimde kumaş iplik yönünde değil çapraz yönde esner; böylece dokuma kumaş vücudu saran akışkan bir döküm kazanır.'),
  ('Bir konfeksiyon atölyesi aynı anda yüzlerce parçayı tek kesimde elde etmek için kumaşı kat kat üst üste seriyor. Bu serime ne ad verilir?', 'Pastal', ['Prova', 'Teyel', 'Ram'], 'Pastal serimi aynı anda çok sayıda katın kesilmesini sağlar; kalıpların yerleşimi kumaş israfını en aza indirecek biçimde planlanır.'),
  ('Bir pastal planında 4 metrekarelik kumaş alanına toplam 3,4 metrekarelik kalıp parçası yerleştirilmiştir. Bu pastalın kumaş kullanım verimi yüzde kaçtır?', '%85', ['%80', '%34', '%90'], 'Verim, kalıp alanının kumaş alanına oranıdır: 3,4 / 4 = 0,85, yani %85. Geri kalan %15 fire olur.'),
  ('Avrupa beden sisteminde 38 numara giyen bir kadın, yaygın dönüşüm tablolarına göre İngiltere\'de genellikle hangi bedeni arar?', '10', ['38', '14', '6'], 'Kadın giyiminde AB 38, İngiltere\'de 10 ve ABD\'de 6 bedene karşılık gelir; ülkelerin numaralandırma sistemleri farklıdır.'),
  ('Düğmesi olmayan, boyun kısmında geniş açılıp ceketin yakasının üzerine yatırılan gömlek yakasına ne ad verilir?', 'Apaş yaka', ['Hakim yaka', 'Balıkçı yaka', 'Düğmeli yaka'], 'Apaş yaka açık ve düz yatar; adını 20. yüzyıl başında Paris sokaklarındaki kabadayı gruplarına verilen \'Apaş\' adından alır.'),
  ('Smokinlerde sık görülen, boyundan önden kapanma noktasına kadar çentiksiz ve kesintisiz bir kavisle inen yaka türü hangisidir?', 'Şal yaka', ['Sivri yaka', 'Çentikli yaka', 'Hakim yaka'], 'Şal yakada üst yaka ile klapa arasında bir çentik yoktur; tek parça yumuşak bir kavis oluşturur.'),
  ('Takım elbise ceketlerinin çoğunda görülen, üst yaka ile klapanın birleştiği yerde yana açılan V biçimli bir girinti bulunan yaka türü hangisidir?', 'Çentikli yaka', ['Şal yaka', 'Sivri (kırlangıç) yaka', 'Apaş yaka'], 'Çentikli yakada iki yaka parçası birleşme yerinde V biçiminde bir açıklık bırakır; sivri yakada ise klapanın ucu yukarı doğru kalkar.'),
  ('Uçları yuvarlak, düz yatan küçük çocuk ve kadın giysisi yakası adını 1905\'te sahnelenen bir tiyatro oyununun kahramanından alır. Bu kahraman kimdir?', 'Peter Pan', ['Oliver Twist', 'Pinokyo', 'Alice'], 'Yuvarlak uçlu düz yaka, Peter Pan oyununun kostümlerinde kullanılmasıyla bu adla anılmaya başlamıştır.'),
  ('Gömlek yakası uçlarının küçük düğmelerle gövdeye tutturulduğu yaka türünün, uçların rüzgârda uçuşmasını önlemek için hangi sporun oyuncularından esinlendiği anlatılır?', 'Polo', ['Golf', 'Kriket', 'Tenis'], 'Düğmeli yaka (button-down) 19. yüzyıl sonunda İngiliz polo oyuncularının gömleklerinden esinlenilerek yaygınlaştırılmıştır.'),
  ('Omuz dikişi bulunmayan, koltuk altından yakaya doğru çapraz uzanan dikişlerle bedene bağlanan kol türü hangisidir?', 'Reglan kol', ['Japone kol', 'Takma kol', 'Balon (puf) kol'], 'Reglan kol adını Kırım Savaşı\'ndaki İngiliz komutan Lord Raglan\'dan alır; hareket rahatlığı sağladığı için spor giyimde yaygındır.'),
  ('Baldırın ortasında biten dar pantolon türü, 1950\'lerde moda olan ve adını İtalya\'daki ünlü bir adadan alan hangi pantolondur?', 'Kapri pantolon', ['Bermuda', 'Jodhpur', 'Kargo (körüklü cepli) pantolon'], 'Kapri pantolon adını Napoli Körfezi\'ndeki Capri Adası\'ndan alır; 1950\'lerin film yıldızlarıyla yaygınlaşmıştır.'),
  ('Klasik kumaş pantolonlarda paçanın dışa doğru kıvrılıp sabitlenmesiyle oluşan katlı bitime ne ad verilir?', 'Duble paça', ['İspanyol paça', 'Reglan paça', 'Kloş paça'], 'Duble paça paçaya ağırlık vererek pantolonun düz düşmesine yardım eder; daha çok klasik takım pantolonlarında görülür.'),
  ('Ahşap ya da boynuz geçme düğmeleri ve kapüşonuyla tanınan, Türkçede bir İngiliz mareşalinin adıyla anılan kalın yün kaban hangisidir?', 'Montgomeri', ['Trençkot', 'Redingot', 'Frak'], 'Montgomeri (İng. duffle coat), İkinci Dünya Savaşı\'nda Mareşal Montgomery\'nin sık giymesiyle bu adla anılmıştır.'),
  ('Blazer ceketin adının, 19. yüzyılda Cambridge\'deki bir kürek kulübünün parlak kırmızı ceketlerinden geldiği anlatılır. İngilizce \'blaze\' sözcüğü hangi anlamı taşır?', 'Alev, parlayarak yanmak', ['Kürek çekmek', 'Kulüp üyesi', 'Lacivert renk'], 'Kürekçilerin parlak kırmızı ceketleri \'alev gibi\' parladığı için bu ceketlere \'blazer\' denmiş, ad zamanla tüm spor ceketlere yayılmıştır.'),
  ('Kapüşonlu, rüzgâra ve soğuğa karşı giyilen parka ve anorak giysilerinin kökeni hangi halka dayanır?', 'Arktik İnuit halklarına', ['And Dağları\'ndaki Keçualara', 'Sahra\'daki Tuareglere', 'Avustralya\'daki Aborijinlere'], 'Parka ve anorak sözcükleri ve bu giysilerin biçimi Arktik halkların hayvan derisinden yaptığı kapüşonlu giysilerden gelir.'),
  ('Askerî pilot ceketlerinden gelen MA-1 tipi bomber ceketlerin astarının parlak turuncu olmasının nedeni nedir?', 'Düşen pilotun kolay görülmesi', ['Turuncu boyanın en ucuz boya olması', 'Astarın ısıyı yansıtması', 'Rütbelerin renkle ayırt edilmesi'], 'Bu ceketler acil durumda ters giyilebilecek biçimde tasarlanmıştır; turuncu astar kurtarma ekiplerinin pilotu uzaktan görmesine yardım eder.'),
  ('Türkçede ve birçok Avrupa dilinde \'smokin\' denilen akşam giysisinin adı aslında hangi giysiden gelir?', 'Sigara içerken giyilen ceketten', ['Gece yürüyüşüne çıkılan paltodan', 'Ocak başında giyilen önlükten', 'Tiyatro sahnesi kostümünden'], '19. yüzyılda erkekler sigara içerken giysilerine koku sinmesin diye \'smoking jacket\' giyerdi; Avrupa dilleri bu adı akşam ceketine aktarmıştır.'),
  ('1666\'da İngiltere Kralı II. Charles\'ın sarayda giyilmesini buyurduğu ve bugünkü üç parçalı takım elbisenin kökeni sayılan giysi hangisidir?', 'Ceketin altına giyilen uzun yelek', ['Kuyruklu frak', 'Dizlere inen palto', 'Kollu pelerin'], 'II. Charles\'ın getirdiği ceket, yelek ve pantolon (diz altı külot) üçlüsü, erkek takım elbisesinin atası kabul edilir.'),
  ('İskoç kimyager Charles Macintosh\'un 1820\'lerde iki kat kumaş arasına çözünmüş kauçuk sürerek geliştirdiği malzeme, hangi giysinin İngilizcede onun adıyla anılmasına yol açmıştır?', 'Su geçirmez yağmurluğun', ['Yün balıkçı kazağının', 'Deri pilot ceketinin', 'Pamuklu iş tulumunun'], 'Macintosh\'un su geçirmez kumaşından yapılan yağmurluklar İngilizcede \'mackintosh\' ya da kısaca \'mac\' diye anılır.'),
  ('Bir terzi kışlık bir palto için rüzgâr geçirmeyen, dinklenerek yoğunlaştırılmış yünlü bir kumaş arıyor. Seçenekler arasında hangisini seçmelidir?', 'Kaşe', ['Şifon', 'Poplin', 'Organze'], 'Kaşe kumaş dinkleme (keçeleştirme) ile sıklaşır; rüzgâr geçirmez ve sıcak tutar, bu yüzden palto kumaşı olarak sevilir.'),
  ('Polo tişörtlerinde kullanılan, yüzeyinde küçük petek ya da kabartma desenler bulunan örme kumaş türü hangisidir?', 'Pike', ['Süprem', 'Saten', 'Kadife'], 'Pike örme, yüzeyindeki küçük kabartmalar sayesinde nefes alır ve tene yapışmaz; spor tişörtleri için uygundur.'),
  ('Yakasız, önü yalnız birkaç düğmeli bir patla açılan ve adını İngiltere\'de kürek yarışlarıyla ünlü bir kasabadan alan tişört türü hangisidir?', 'Henley', ['Polo', 'Raglan', 'Guayabera'], 'Henley tişörtleri Henley-on-Thames\'teki kürekçilerin giydiği formalardan adını almıştır.'),
  ('İngilizcede kazak anlamındaki \'sweater\' sözcüğü 19. yüzyılda başlangıçta hangi amaçla giyilen yün giysiyi anlatıyordu?', 'Terleyip kilo vermek için giyilen giysiyi', ['Madencilerin tozdan korunmasını sağlayan giysiyi', 'Denizcilerin yüzerken giydiği giysiyi', 'Çiftçilerin hasatta giydiği giysiyi'], 'Sweat İngilizcede ter demektir; kalın yün kazaklar ilk olarak sporcuların idmanda terleyip kilo vermesi için giyilmiştir.'),
  ('Burun ve kenarlarında süs amaçlı delik dizileri bulunan klasik \'brogue\' ayakkabılardaki deliklerin ilk işlevi neydi?', 'Islak arazide suyun boşalmasını sağlamak', ['Ayakkabıyı daha hafif hâle getirmek', 'Bağcıkları farklı biçimde geçirmek', 'Ayakkabıcının imzasını göstermek'], 'Brogue ayakkabılar İskoçya ve İrlanda\'nın bataklık arazilerinde giyilen kaba ayakkabılardan gelir; delikler suyun dışarı akmasına yarardı.'),
  ('Bağcıksız, kolayca giyilen ve yüzündeki deri bantta küçük bir yarık bulunan ayakkabılara İngilizcede \'penny loafer\' denmesinin nedeni olarak ne anlatılır?', 'Gençlerin bu yarığa bozuk para koyması', ['Ayakkabının bir peniye satılması', 'Penny adlı bir ayakkabıcının modeli bulması', 'Bantın madeni paradan yapılması'], '1950\'lerde Amerikalı gençlerin bu bantlardaki yarığa bir penilik bozuk para yerleştirdiği anlatılır; model bu yüzden \'penny loafer\' adını almıştır.'),
  ('Kuzey Amerika yerli halklarından kaynaklanan, tabanı ve yanları tek parça yumuşak deriden yapılıp üstüne ayrı bir parça dikilen ayakkabı hangisidir?', 'Mokasen', ['Espadril', 'Oxford', 'Galoş'], 'Mokasende deri ayağın altından sarılarak yukarı kaldırılır; sert bir taban yoktur ve ayak yere yakın hisseder.'),
  ('Çok ince ve yüksek topuklu kadın ayakkabılarına verilen \'stiletto\' adı İtalyancada neyi anlatır?', 'İnce uçlu küçük bir hançeri', ['Yüksek bir kule çatısını', 'Uzun bacaklı bir su kuşunu', 'Dar bir sokak türünü'], 'Stiletto ince ve sivri bir hançerdir; 1950\'lerde yaygınlaşan ince yüksek topuk bu silaha benzetilmiştir.'),
  ('Gaziantep\'te el yapımı olarak üretilen, ince ve hafif tabanlı, bağcıksız geleneksel deri ayakkabı hangisidir?', 'Yemeni', ['Çizme', 'Postal', 'Galoş'], 'Yemeni (Antep yemenisi) yumuşak deriden elde dikilen, hafif ve rahat bir ayakkabıdır; coğrafi işaretle de korunmaktadır.'),
  ('Klasik erkek ayakkabılarında \'Goodyear dikişli\' taban yapısının sağladığı başlıca üstünlük hangisidir?', 'Tabanın defalarca değiştirilebilmesi', ['Ayakkabının su geçirmez olması', 'Tabanın hiç aşınmaması', 'Ayakkabının çok hafif olması'], 'Bu yapıda taban, yüze doğrudan değil ara bir şeride (welt) dikilir; aşınan taban sökülüp yenisi takılabilir.'),
  ('Kauçuk tabanlı spor ayakkabılara İngilizcede \'sneaker\' denmesi bu ayakkabıların hangi özelliğiyle ilgilidir?', 'Sessizce yürümeye elverişli olması', ['Yılan derisinden yapılmaları', 'Hızlı koşuya uygun sivri tabanları', 'İlk kez bir hapishanede üretilmeleri'], 'Sneak İngilizcede sinsice, sessizce yürümek demektir; kauçuk tabanlar deri tabanlar gibi ses çıkarmadığı için bu ad verilmiştir.'),
  ('Kauçuktan yapılan diz altı yağmur çizmelerine İngilizcede \'wellies\' denmesi hangi kişinin adına bağlanır?', 'Wellington Dükü', ['Lord Byron', 'Amiral Nelson', 'Kraliçe Victoria'], 'Wellington Dükü kendisi için uyarlattığı deri çizmeleri yaygınlaştırmıştır; sonradan kauçuktan yapılan benzer çizmeler de bu adla anılmıştır.'),
  ('Fötr şapkanın adı Fransızcada hangi malzemeyi anlatır?', 'Keçe', ['Hasır', 'Deri', 'İpek'], 'Fötr (Fr. feutre) keçe demektir; bu şapkalar keçeleştirilmiş yün ya da tavşan tüyünden yapılır.'),
  ('Yuvarlak ve sert tepeli melon şapka (İng. bowler) 1849\'da Londra\'da ilk tasarlandığında hangi amaca hizmet etmesi istenmişti?', 'Av bekçilerini alçak dallardan korumak', ['Bankacıların resmî kıyafetini tamamlamak', 'Askerlerin başını kurşundan korumak', 'Sihirbazların gösterilerinde kullanılmak'], 'Melon şapka, at üstündeki av bekçilerinin silindir şapkalarının dallara takılması sorununa çözüm olarak sert ve alçak tasarlanmıştır.'),
  ('Tepesi ortadan çökertilmiş, kenarları esnek yumuşak keçe şapka \'fedora\' adını hangi kaynaktan alır?', 'Bir tiyatro oyununun kahramanından', ['İtalya\'daki bir dağ kasabasından', 'Şapkayı icat eden bir terziden', 'Bir Rus prensesinin takma adından'], 'Victorien Sardou\'nun 1882 tarihli \'Fédora\' oyununda başrol oyuncusu bu tür bir şapka takmış, şapka oyunun adıyla anılmaya başlamıştır.'),
  ('Sert hasırdan yapılan, düz ve yassı tepeli, genellikle kurdeleli yazlık şapkaya Türkçede ne ad verilir?', 'Kanotiye', ['Fötr', 'Silindir', 'Kasket'], 'Kanotiye (Fr. canotier, kayıkçı) adını 19. yüzyılda kürek çeken ve kayık gezintisi yapanların bu şapkayı takmasından alır.'),
  ('Yumuşak, yuvarlak ve düz biçimli keçe başlık olan bere geleneksel olarak hangi bölgenin halkıyla özdeşleşmiştir?', 'Bask Ülkesi', ['Toskana', 'Bavyera', 'Flandre'], 'Bere, Pireneler\'in batısındaki Bask ve Béarn yöresinin geleneksel başlığıdır; sonra Fransız kimliğiyle de özdeşleşmiştir.'),
  ('Kenarsız, kısa silindir biçimindeki \'pillbox\' kadın şapkasını 1961\'de ABD başkanının yemin töreninde takarak üne kavuşturan kişi kimdir?', 'Jacqueline Kennedy', ['Grace Kelly', 'Marilyn Monroe', 'Audrey Hepburn'], 'Jacqueline Kennedy\'nin John F. Kennedy\'nin yemin töreninde taktığı pillbox şapka 1960\'ların başında büyük bir moda akımı başlatmıştır.'),
  ('İngilizcedeki \'şapkacı kadar deli\' deyiminin, 18-19. yüzyıl şapkacılığındaki hangi uygulamaya dayandığı düşünülür?', 'Keçe yapımında cıva bileşiklerinin kullanılmasına', ['Şapkacıların gece gündüz çalıştırılmasına', 'Şapka boyalarının alkolle karıştırılmasına', 'Şapkaların kurşunla ağırlaştırılmasına'], 'Kürkü keçeleştirmek için kullanılan cıva nitrat şapkacılarda titreme ve ruhsal bozukluklara yol açan cıva zehirlenmesine neden oluyordu.'),
  ('\'Kravat\' sözcüğünün, 17. yüzyılda Fransa\'da boyunlarına bağladıkları renkli atkılarla dikkat çeken hangi askerlerin adından geldiği kabul edilir?', 'Hırvat askerlerinin', ['İsviçreli muhafızların', 'İskoç tüfekçilerin', 'Macar süvarilerinin'], 'Otuz Yıl Savaşları sırasında Fransa\'da bulunan Hırvat askerlerinin boyun atkıları moda olmuş; Fransızca \'cravate\' sözcüğü \'Hrvat\' adından türemiştir.'),
  ('Papyon sözcüğü Fransızcada hangi anlama gelir?', 'Kelebek', ['Yaprak', 'Kurdele', 'Düğüm'], 'Papyon (Fr. papillon) kelebek demektir; kanatları açılmış bir kelebeği andıran biçimi nedeniyle bu adı almıştır.'),
  ('Gündüz resmî kıyafetle takılan, gömlek yakasının içine yerleştirilen geniş ve dökümlü boyun bağı \'askot\' adını hangi yerden alır?', 'Ünlü bir İngiliz at yarışı pistinden', ['İskoçya\'daki bir yün fabrikasından', 'Fransa\'daki bir saray bahçesinden', 'Londra\'daki bir tiyatrodan'], 'Askot, İngiltere\'deki Ascot at yarışlarına katılan seçkinlerin taktığı boyun bağıdır.'),
  ('Kravatta geniş ve simetrik üçgen bir düğüm oluşturan, geniş yakalı gömleklerle önerilen klasik bağlama yöntemi hangi adla anılır?', 'Windsor düğümü', ['Oxford düğümü', 'Kelebek düğüm', 'Gemici düğümü'], 'Windsor düğümü adını İngiliz kraliyet ailesinin Windsor hanedanından alır; dört elli (four-in-hand) düğüme göre daha geniş ve dolgundur.'),
  ('Antik Mısır\'da soyluların ve rahiplerin başlarını tıraş ettirip peruk takmalarının başlıca nedenlerinden biri olarak ne gösterilir?', 'Sıcakta temizlik ve bitten korunma', ['Saç boyamanın dinsel olarak yasak olması', 'Perukların savaşta başı koruması', 'Saç uzatmanın yalnız kölelere ayrılması'], 'Tıraşlı baş sıcakta serinlik ve temizlik sağlıyordu; peruklar ise hem güneşten korur hem de toplumsal konumu gösterirdi.'),
  ('Antik Yunan\'da kadın ve erkeklerin giydiği, dikdörtgen bir kumaşın omuzlardan iğnelerle tutturulup belden kuşakla bağlandığı tunik hangisidir?', 'Khiton', ['Toga', 'Stola', 'Shendyt'], 'Khiton dikiş gerektirmeyen ya da az dikişli bir giysiydi; kumaş omuzlarda iğneyle tutturularak bedene dökümlü biçimde sarılırdı.'),
  ('Bir arkeolog Roma dönemine ait bir mezarda, kumaşı omuzda tutturmaya yarayan ve çengelli iğneye benzeyen süslü bronz bir toka buluyor. Bu buluntunun adı nedir?', 'Fibula', ['Toga', 'Kaunakes', 'Tunika'], 'Fibula dikişsiz giysilerin bedende durmasını sağlayan en önemli aksesuardı; arkeolojide dönemleri tarihlemek için de kullanılır.'),
  ('Antik Roma\'da toga giyme hakkı genel olarak kime aitti?', 'Özgür doğmuş erkek yurttaşlara', ['Yalnız imparator ve ailesine', 'Kadın ve erkek bütün kölelere', 'Roma\'daki yabancı tüccarlara'], 'Toga Roma yurttaşlığının simgesiydi; yabancıların ve kölelerin toga giymesi yasaktı, saygın kadınlar ise stola giyerdi.'),
  ('İngilizce \'candidate\' (aday) sözcüğü, Roma\'da seçimlerde görev isteyenlerin giydiği hangi giysiyle ilişkilidir?', 'Ağartılmış bembeyaz bir togayla', ['Mor kenarlı bir tunikle', 'Altın işlemeli bir pelerinle', 'Siyah yünden bir mantoyla'], 'Latince \'candidus\' parlak beyaz demektir; görev isteyenler dikkat çekmek için ağartılmış \'toga candida\' giyer ve \'candidatus\' diye anılırdı.'),
  ('Roma İmparatorluğu döneminde tümüyle mor renkli bir giysiyi giyme hakkı zamanla kime ayrılmıştı?', 'İmparatora', ['Bütün senatörlere', 'Gladyatörlere', 'Tüm rahiplere'], 'Çok pahalı olan mor boya imparatorluk gücünün simgesiydi; tümü mor giysi imparatora ayrılmış, \'mor giymek\' tahta çıkmak anlamına gelmiştir.'),
  ('Kenarında mor bir şerit bulunan \'toga praetexta\' Roma\'da başlıca kimler tarafından giyilirdi?', 'Yüksek memurlar ve özgür çocuklar', ['Köleler ve azatlılar', 'Askerler ve gladyatörler', 'Yabancı elçiler ve tüccarlar'], 'Toga praetexta konsül gibi yüksek görevlilerin ve ergenliğe kadar özgür doğmuş çocukların giysisiydi; erkek çocuklar yetişkinlikte düz beyaz togaya geçerdi.'),
  ('Bir kostümcü, 15. yüzyıl Burgonya sarayında geçen bir oyun için soylu kadın oyunculara ucundan tül sarkan uzun konik başlıklar hazırlıyor. Bu başlıkların adı nedir?', 'Hennin', ['Bere', 'Kanotiye', 'Fes'], 'Hennin bugün masallardaki prenses başlıklarıyla özdeşleşmiştir; yüksekliği zaman zaman bir metreye yaklaşırdı.'),
  ('Orta Çağ ve Rönesans Avrupa\'sında hangi sınıfın hangi kumaşları, renkleri ve süsleri giyebileceğini belirleyen yasalara ne ad verilir?', 'Lüks (israf) yasaları', ['Lonca tüzükleri', 'Gümrük yasaları', 'Vergi defterleri'], 'Lüks yasaları sınıflar arası farkı görünür kılmayı ve aşırı harcamayı önlemeyi amaçlar; örneğin bazı kürk ve renkleri yalnız soylulara ayırırdı.'),
  ('Avrupa\'da kraliyet pelerinlerinde ve yargıç cüppelerinde görülen, siyah kuyruk uçlarıyla beneklenmiş beyaz kürk hangi hayvanın kış kürküdür?', 'Kakım', ['Beyaz tilki', 'Kutup tavşanı', 'Vizon'], 'Kakım (ermin) kışın beyaza döner, yalnız kuyruğunun ucu siyah kalır; bu siyah uçlar beyaz kürke benek olarak dikilir.'),
  ('Bir kostümcü I. Elizabeth dönemini canlandıran bir oyun için oyunculara boynu tekerlek gibi saran, kolalı ve kat kat kıvrımlı yakalar hazırlıyor. Bu yaka türü hangisidir?', 'Kırma yaka', ['Apaş yaka', 'Şal yaka', 'Kayık yaka'], 'Ruff denen kırma yakalar kolayla sertleştirilir ve kıvrımları özel ütülerle biçimlendirilirdi; I. Elizabeth portrelerinde sıkça görülür.'),
  ('16. yüzyılda İspanyol sarayının etkisiyle Avrupa\'da soyluluğun, ciddiyetin ve zenginliğin simgesi olarak moda olan giysi rengi hangisidir?', 'Siyah', ['Turuncu', 'Açık yeşil', 'Gök mavisi'], 'Derin ve kalıcı bir siyah elde etmek pahalıydı; İspanyol sarayında yaygınlaşan siyah giysiler zamanla Avrupa\'nın birçok sarayında prestij rengi oldu.'),
  ('Kenarları sivri dişlerle biten geniş dantel yaka, 17. yüzyılda portrelerinde sık resmettiği için hangi ressamın adıyla anılır?', 'Anthony van Dyck', ['Rembrandt', 'Vermeer', 'Francisco Goya'], 'Van Dyck yakası ve sivri uçlu \'Van Dyck sakalı\' ressamın İngiliz sarayında yaptığı portrelerdeki modadan adını alır.'),
  ('XIV. Louis döneminde Fransız sarayında yalnız soylulara ayrılan ve onların ayrıcalığını gösteren ayakkabı ayrıntısı hangisidir?', 'Kırmızı renkli topuklar', ['Gümüş tokalı bağcıklar', 'Sivri uzun burunlar', 'Altın işlemeli tabanlar'], 'XIV. Louis kırmızı topuklu ayakkabıları saraya kabul edilen soylulara özgü kılmıştı; kırmızı topuk ayrıcalığın simgesi oldu.'),
  ('Fotoğraf ve moda dergileri yaygınlaşmadan önce, Paris\'teki son modayı Avrupa saraylarına tanıtmak için hangi yöntem kullanılıyordu?', 'Son modayla giydirilmiş bebekler yollamak', ['Saray ressamlarını Paris\'e sürgüne yollamak', 'Kumaş örneklerini posta güvercinleriyle yollamak', 'Modacıları tüm saraylarda daimî çalıştırmak'], 'Moda bebekleri (Pandora) minyatür giysiler, saç modelleri ve aksesuarlarla donatılıp Londra\'dan Viyana\'ya kadar gönderilirdi.'),
  ('18. yüzyıl Fransız sarayını canlandıran bir filmde kadın oyuncuların eteklerinin yalnız kalçalardan yanlara doğru genişlemesi isteniyor. Kostümcü hangi iç iskeleti kullanmalıdır?', 'Panier', ['Tournure', 'Verdugado', 'Korse'], 'Panier (sepet) bazı saray elbiselerinde eteği o kadar genişletirdi ki kadınlar kapılardan yan dönerek geçmek zorunda kalırdı.'),
  ('Kraliçe Marie Antoinette\'in giysilerini hazırlayan ve etkisi nedeniyle alaycı biçimde \'moda bakanı\' diye anılan modacı kimdir?', 'Rose Bertin', ['Coco Chanel', 'Madame de Pompadour', 'Jeanne Lanvin'], 'Rose Bertin kraliçenin yakın danışmanı olmuş, kendi adıyla tanınan ilk modacılardan biri sayılmıştır.'),
  ('Marie Antoinette\'in 1783\'te ince beyaz muslinden, bele kuşakla bağlanan sade bir elbiseyle resmedilmesi neden skandal yaratmıştır?', 'Bir iç giysiye benzetilmesi', ['Elbisenin düşman bir ülkeden alınması', 'Portrenin kilisede sergilenmesi', 'Elbisenin erkek giysisi sayılması'], 'Bu sade elbise (chemise à la reine) halk gözünde iç gömleğe benzetildi; portre sergiden kaldırılıp yeniden resimletildi.'),
  ('Fransız Devrimi\'nde halk tabakasından devrimcilere \'sans-culottes\' (külotsuzlar) denmesinin nedeni hangisidir?', 'Diz altı külot yerine uzun pantolon giymeleri', ['Hiçbir zaman pantolon giymemeleri', 'Yalnız kırmızı giysi giymeleri', 'Ayakkabı yerine çıplak ayak yürümeleri'], 'Soylular ipek çorapla diz altı külot giyerdi; işçi ve zanaatkârlar ise uzun pantolon giyiyordu. Bu giysi farkı siyasal bir kimliğe dönüştü.'),
  ('19. yüzyılın başında Londra\'da sade ama kusursuz dikilmiş koyu renk giysiler ve özenle bağlanmış kravatlarla erkek modasını değiştiren ünlü \'dandy\' kimdir?', 'Beau Brummell', ['Oscar Wilde', 'Lord Byron', 'Charles Dickens'], 'George \'Beau\' Brummell, 18. yüzyılın süslü erkek modası yerine sadelik, temizlik ve iyi kesimi öne çıkararak modern takım elbisenin yolunu açmıştır.'),
  ('1880\'lerde geçen bir dizide kadın kostümlerinin yalnız arka tarafı kabarık görünmelidir. Kostümcü eteğin altına hangisini yerleştirmelidir?', 'Tournure', ['Panier', 'Verdugado', 'Krinolin'], 'Tournure (İng. bustle) krinolinin yerini almış, kadın siluetinin hacmini arkaya taşımıştır.'),
  ('Giysilerine kendi adını taşıyan etiketi diken, koleksiyonlarını canlı mankenlere giydirerek sunan ve haute couture\'ün kurucusu sayılan 19. yüzyıl modacısı kimdir?', 'Charles Frederick Worth', ['Paul Poiret', 'Christian Dior', 'Rose Bertin'], 'İngiliz asıllı Worth, Paris\'te açtığı moda eviyle modacıyı sanatçı konumuna yükseltmiş ve sezonluk koleksiyon fikrini başlatmıştır.'),
  ('1850\'lerde ABD\'de kadın hakları savunucularının benimsediği, diz altı bir eteğin altına giyilen bol pantolona adını veren kişi kimdir?', 'Amelia Bloomer', ['Susan B. Anthony', 'Florence Nightingale', 'Harriet Beecher Stowe'], 'Amelia Bloomer bu giysiyi dergisinde savunmuş, giysi onun adıyla \'bloomers\' diye anılmıştır.'),
  ('1900\'lerin ilk on yılında kadınları sıkı korseden kurtaran ve Doğu\'dan esinlenen şalvar ile kaftan biçimli giysileriyle tanınan Fransız modacı kimdir?', 'Paul Poiret', ['Charles Frederick Worth', 'Christian Dior', 'Hubert de Givenchy'], 'Poiret, korsesiz ve dökümlü siluetleri, canlı renkleri ve oryantalist esinli tasarımlarıyla 20. yüzyıl başının en etkili modacılarındandı.'),
  ('1910 dolaylarında moda olan, ayak bileği çevresinde öyle daralan ki giyen kadının ancak küçük adımlarla yürüyebildiği etek türüne ne ad verilir?', 'Aksak etek', ['Kloş etek', 'Pantolon etek', 'Tulip etek'], 'Hobble skirt korseyi bırakan modanın tuhaf bir paradoksuydu: bedeni serbestleştirirken kadınların adımlarını kısıtlıyordu.'),
  ('Vogue dergisinin 1926\'da, otomobil gibi herkesin edinebileceği bir standart olacağını öngörerek \'Chanel\'in Ford\'u\' diye nitelediği tasarım hangisidir?', 'Küçük siyah elbise', ['Tüvit döpiyes', 'Kapitone çanta', 'Denizci çizgili tişört'], 'Chanel\'in sade, uzun kollu siyah elbisesi Ford\'un Model T\'si gibi yaygın ve zamansız bir temel parça olarak görülmüştü.'),
  ('Coco Chanel\'in 1910\'larda o güne dek daha çok erkek iç çamaşırlarında kullanılan hangi kumaşı kadın giysilerinde kullanarak dikkat çektiği bilinir?', 'Jarse', ['Brokar', 'Tafta', 'Kadife'], 'Ucuz ve rahat bir örme kumaş olan jarse, Chanel\'in elinde sade ve hareket özgürlüğü sağlayan şık kadın giysilerine dönüştü.'),
  ('1920 ve 1930\'larda verev kesimi ustalıkla kullanarak vücudu saran dökümlü elbiseler yapan ve \'terzilerin mimarı\' diye anılan Fransız modacı kimdir?', 'Madeleine Vionnet', ['Jeanne Lanvin', 'Coco Chanel', 'Elsa Schiaparelli'], 'Vionnet tasarımlarını küçük ahşap mankenler üzerinde kumaşı dökerek geliştirirdi; verev kesimi moda tarihinde onunla özdeşleşmiştir.'),
  ('Salvador Dalí ile birlikte üzerinde dev bir ıstakoz resmi bulunan elbise tasarlayan ve \'şok pembe\' rengiyle anılan İtalyan asıllı modacı kimdir?', 'Elsa Schiaparelli', ['Madeleine Vionnet', 'Coco Chanel', 'Miuccia Prada'], 'Schiaparelli sürrealist sanatçılarla iş birliği yapmış, esprili ve sanatsal tasarımlarıyla 1930\'ların modasına damga vurmuştur.'),
  ('Christian Dior\'un 1947\'de tanıttığı \'New Look\' koleksiyonu neden bazı çevrelerde tepkiyle karşılanmıştır?', 'Kıtlık döneminde çok fazla kumaş harcaması', ['Kadınlara ilk kez pantolon giydirmesi', 'Yalnız siyah renk kullanması', 'Eteklerin dizin çok üstünde bitmesi'], 'Karne uygulamasının sürdüğü yıllarda bir eteğe metrelerce kumaş harcanması savurganlık olarak eleştirilmiş, kimi gösterilerde protesto yaşanmıştır.'),
  ('İkinci Dünya Savaşı sırasında İngiltere\'de kumaş ve işçilikten tasarruf etmek için uygulanan \'Utility\' giysi programı ne öngörüyordu?', 'Cep, pili ve süslerin sınırlandırılmasını', ['Bütün giysilerin askerî renklerde üretilmesini', 'Giysilerin yalnız ithal kumaştan yapılmasını', 'Kadınların pantolon giymesinin yasaklanmasını'], 'Utility giysilerinde kumaş miktarı, düğme sayısı, pili ve cep gibi ayrıntılar kurallarla sınırlandırılmış; tasarım sade ama işlevsel tutulmuştu.'),
  ('İkinci Dünya Savaşı yıllarında çorap bulamayan bazı kadınların bacaklarına boya sürüp arka tarafa kalemle dikey bir çizgi çizmesinin amacı neydi?', 'Dikişli çorap giyiyormuş gibi görünmek', ['Varis damarlarını gizlemek', 'Bacakları güneşten korumak', 'Askerî bir işaret taşımak'], 'Dönemin ince çoraplarının arkasında boydan boya bir dikiş bulunurdu; çizgi bu dikişi taklit ederek çorap yanılsaması yaratıyordu.'),
  ('1960\'larda \'Swinging London\' gençlik modasının merkezi olan ve küçük butikleriyle ünlenen Londra sokağı hangisidir?', 'Carnaby Street', ['Savile Row', 'Bond Street', 'Fleet Street'], 'Carnaby Street\'teki butikler renkli, ucuz ve hızla değişen gençlik modasını sundu; Savile Row ise klasik ısmarlama terzilikle tanınır.'),
  ('Yves Saint Laurent\'ın 1966\'da kadın modasına kazandırdığı ve o yıllarda kimi lüks lokantalarda pantolonlu kadınların içeri alınmaması nedeniyle tartışma yaratan tasarım hangisidir?', 'Kadınlar için smokin', ['Mini etek', 'Bikini', 'Sargı elbise'], '\'Le Smoking\' adlı kadın smokini erkek giyiminin bir simgesini kadınlara uyarlamış, kadın pantolonunun resmî ortamlarda kabulünü hızlandırmıştır.'),
  ('1970\'lerin ortasında Malcolm McLaren ile birlikte işlettiği Londra butiği üzerinden punk modasını biçimlendiren modacı kimdir?', 'Vivienne Westwood', ['Mary Quant', 'Zandra Rhodes', 'Jean Muir'], 'Westwood\'un deri, zincir, çengelli iğne ve provokatif baskılı tişörtleri punk estetiğinin temelini oluşturdu.'),
  ('Punk modasında giysilerin çengelli iğnelerle tutturulması ve bilerek yırtılması en çok hangi tavrı yansıtıyordu?', 'Düzene ve tüketim kültürüne başkaldırıyı', ['Zenginliği ve soyluluğu göstermeyi', 'Askerî disiplini övmeyi', 'Geleneksel terziliğe bağlılığı'], 'Punk, işsizlik ve toplumsal huzursuzluk ortamında gençlerin öfkesini yansıttı; yıpranmış, kendin yap estetiği bilinçli bir meydan okumaydı.'),
  ('1980\'lerde iş dünyasında kadınların otorite ve güveni vurgulamak için giydiği geniş vatkalı ceketli takımlarla özdeşleşen akım hangisidir?', 'Güç giyimi', ['Grunge', 'Minimalizm', 'Bohem tarz'], 'Güç giyimi kadınların yönetim kademelerinde artan varlığıyla birlikte yaygınlaştı; geniş omuzlar erkek takımının otoritesini çağrıştırıyordu.'),
  ('1974\'te tanıttığı, önden sarılıp bağlanan jarse elbise (wrap dress) ile ünlenen modacı kimdir?', 'Diane von Fürstenberg', ['Donna Karan', 'Vera Wang', 'Carolina Herrera'], 'Sargı elbise, çalışan kadınlar için hem rahat hem şık bir seçenek olarak 1970\'lerin simgelerinden oldu.'),
  ('Christian Dior\'un \'hepimizin ustası\' diye andığı, heykelsi ve mimari kesimleriyle tanınan İspanyol modacı kimdir?', 'Cristóbal Balenciaga', ['Paco Rabanne', 'Manolo Blahnik Rodríguez', 'Antonio Berardi'], 'Balenciaga kumaşı vücuttan uzaklaştıran yeni siluetleriyle (balon etek, çuval elbise) 1950\'lerin en saygın modacılarından biriydi.'),
  ('Audrey Hepburn\'ün 1961 yapımı \'Tiffany\'de Kahvaltı\' filminin açılış sahnesinde giydiği siyah elbiseyi tasarlayan Fransız modacı kimdir?', 'Hubert de Givenchy', ['Yves Saint Laurent', 'Pierre Cardin', 'Christian Lacroix'], 'Givenchy ile Audrey Hepburn arasındaki uzun dostluk, modacı ile oyuncu arasındaki en ünlü iş birliklerinden biri sayılır.'),
  ('Giysiyi önce bol kesip diktikten sonra ısıyla pliseleyen yöntemi ve \'Pleats Please\' serisiyle tanınan Japon tasarımcı kimdir?', 'Issey Miyake', ['Kenzo Takada', 'Rei Kawakubo', 'Hanae Mori'], 'Miyake\'nin yönteminde kumaş değil bitmiş giysi pliselenir; ortaya hafif, buruşmayan ve kolay bakılan giysiler çıkar.'),
  ('1983\'ten 2019\'daki ölümüne kadar Chanel moda evinin yaratıcı direktörlüğünü yapan Alman tasarımcı kimdir?', 'Karl Lagerfeld', ['Jil Sander', 'Wolfgang Joop', 'Helmut Lang'], 'Lagerfeld, durgunluk dönemindeki Chanel\'i yeniden canlandırmış; aynı zamanda Fendi\'de de onlarca yıl çalışmıştır.'),
  ('Moda dünyasında kendi adıyla anılan özel bir kırmızı tonuyla özdeşleşen İtalyan modacı kimdir?', 'Valentino Garavani', ['Giorgio Armani', 'Gianni Versace', 'Miuccia Prada'], 'Valentino koleksiyonlarında her zaman yer verdiği canlı kırmızıyla tanınır; bu ton \'Valentino kırmızısı\' diye anılır.'),
  ('Erkek ceketinden vatka ve sert ara astarları çıkararak \'yapısız ceket\' anlayışını yaygınlaştıran ve 1980 yapımı \'American Gigolo\' filminin kostümleriyle ünlenen İtalyan modacı kimdir?', 'Giorgio Armani', ['Valentino Garavani', 'Gianni Versace', 'Ermenegildo Zegna'], 'Armani\'nin yumuşak omuzlu, rahat dökümlü ceketleri 1980\'lerde erkek ve kadın iş giyimini derinden etkiledi.'),
  ('Adını taşıyan lisanslı ürünleri giysiden kalem ve tencereye kadar yüzlerce alana yayarak moda lisanslamasının öncüsü sayılan modacı kimdir?', 'Pierre Cardin', ['Hubert de Givenchy', 'Christian Dior', 'Pierre Balmain'], 'Cardin, moda evinin adını çok çeşitli ürünlere lisanslayarak büyük bir servet edinmiş, bu iş modelinin örneği olmuştur.'),
  ('2000 yılındaki bir gösterisinde ahşap bir sehpayı katlanabilen bir etek hâline getirerek mankene giydiren Kıbrıs doğumlu tasarımcı kimdir?', 'Hüseyin Çağlayan', ['Rifat Özbek', 'Atıl Kutoğlu', 'Cemil İpekçi'], 'Çağlayan\'ın \'Afterwords\' koleksiyonunda mobilyalar giysiye dönüşüyordu; gösteri göç ve yerinden edilme temalarını işliyordu.'),
  ('Madonna\'nın 1990 dünya turnesinde giydiği konik sütyenli korseyi tasarlayan Fransız modacı kimdir?', 'Jean Paul Gaultier', ['Thierry Mugler', 'Christian Lacroix', 'Azzedine Alaïa'], 'Gaultier\'nin konik sütyen tasarımı pop kültürünün en tanınmış sahne kostümlerinden biri olmuştur.'),
  ('Fransa\'da bir moda evinin \'haute couture\' unvanını kullanabilmesi için ne gerekir?', 'Yetkili federasyonun ölçütlerini karşılayıp onay almak', ['Paris\'te en az bir mağaza kiralamış olmak', 'Yalnız Fransız vatandaşı tasarımcı çalıştırmak', 'Her yıl en az bin elbise satmak'], 'Haute couture yasayla korunan bir unvandır; Paris\'te atölye, el işçiliği ve düzenli koleksiyon gösterimi gibi koşulları sağlayan evler onaylanır.'),
  ('Kadın hazır giyimde \'sonbahar-kış\' koleksiyonlarının büyük moda haftalarında gösterildiği dönem genellikle hangisidir?', 'Bir önceki şubat-mart', ['Aynı yılın ekim ve kasım ayları', 'Bir önceki aralık ayı', 'Aynı yılın temmuz ayı'], 'Koleksiyonlar satış mevsiminden aylar önce gösterilir; böylece mağazalar sipariş verip üretim yapılabilir.'),
  ('Bir koleksiyonun parçalarını kombinleriyle birlikte gösteren ve alıcılara ya da basına dağıtılan fotoğraf kataloğuna moda sektöründe ne ad verilir?', 'Lookbook', ['Moodboard', 'Tech pack', 'Showroom'], 'Lookbook koleksiyonun görsel özetidir; moodboard ise tasarım sürecindeki esin panosu, tech pack üretim için teknik dosyadır.'),
  ('Haute couture atölyelerinde asıl kumaş kesilmeden önce kalıbı ve duruşu denemek için ucuz ham pamuklu bezden dikilen deneme giysisine ne ad verilir?', 'Toile', ['Pastal', 'Lookbook', 'Defile'], 'Toile (Fr. bez) üzerinde düzeltmeler yapılır, ardından onaylanan kalıp pahalı kumaşa aktarılır.'),
  ('Vogue dergisi ilk kez 1892\'de hangi kentte yayımlanmaya başlamıştır?', 'New York', ['Paris', 'Londra', 'Milano'], 'Vogue New York\'ta haftalık bir sosyete dergisi olarak doğdu; 1909\'dan sonra moda dergisine dönüşüp başka ülkelere yayıldı.'),
  ('Alexander McQueen, John Galliano ve Stella McCartney gibi tasarımcıların mezun olduğu Londra\'daki sanat ve tasarım okulu hangisidir?', 'Central Saint Martins', ['Parsons', 'Royal Ballet School', 'Bauhaus Okulu'], 'Central Saint Martins moda eğitiminde dünyanın en tanınmış okullarından biridir; Parsons ise New York\'tadır.'),
  ('Fotoğraf yaygınlaşmadan önce 18. ve 19. yüzyıl dergilerinde son modayı göstermek için yayımlanan, çoğu elle renklendirilmiş çizimlere ne ad verilirdi?', 'Moda gravürü', ['Gazete karikatürü', 'Kartpostal', 'Afiş'], 'Moda gravürleri (fashion plate) giysilerin kesimini, rengini ve aksesuarlarını ayrıntılı biçimde göstererek terziler ve okurlar için rehber olurdu.'),
  ('Osmanlı padişahlarının giysilerinin ölümlerinden sonra bohçalara konup etiketlenerek saklanması geleneği sayesinde bugün dünyanın en zengin kaftan koleksiyonlarından biri hangi müzededir?', 'Topkapı Sarayı Müzesi', ['Ayasofya Müzesi', 'Dolmabahçe Sarayı', 'Ankara Etnografya Müzesi'], 'Padişah giysilerinin özenle korunması sayesinde Topkapı Sarayı\'nda 15. yüzyıldan itibaren yüzlerce kaftan ve giysi günümüze ulaşmıştır.'),
  ('Osmanlı sarayında yabancı elçilere ve başarılı devlet adamlarına bir itibar göstergesi olarak giydirilen değerli kaftana ne ad verilirdi?', 'Hil\'at', ['Ferace', 'Entari', 'Yelek'], 'Hil\'at giydirmek padişahın lütfunu ve konuğa verdiği değeri gösteren bir törendi; kaftanın kumaşı kişinin derecesine göre seçilirdi.'),
  ('Osmanlı kadınlarının sokağa çıkarken giysilerinin üzerine giydiği geniş, uzun ve kollu dış giysiye ne ad verilir?', 'Ferace', ['Entari', 'Mintan', 'Salta'], 'Ferace kadınların dış giysisiydi; 19. yüzyılda renkleri ve kumaşları modaya göre değişmiş, zamanla yerini çarşafa ve mantoya bırakmıştır.'),
  ('Osmanlı kadınlarının feraceyle birlikte kullandığı, başı saran ve yüzün alt kısmını örten ince tülbent örtüye ne ad verilir?', 'Yaşmak', ['Ehram', 'Kuşak', 'Yazma'], 'Yaşmak iki parça ince tülbentten oluşurdu; 19. yüzyılda giderek incelmiş ve yüzü belli eden süsleyici bir öğeye dönüşmüştü.'),
  ('Osmanlı kadın ve erkek giyiminde iç gömleğin üzerine giyilen, önden açık, uzun ve genellikle yanları yırtmaçlı elbiseye ne ad verilir?', 'Entari', ['Ferace', 'Kaftan', 'Cübbe'], 'Entari ev içinde de giyilen temel giysiydi; üzerine kuşak bağlanır, dışarı çıkarken üstüne kaftan ya da ferace giyilirdi.'),
  ('Padişahların ve yüksek rütbeli kişilerin sarıklarına taktığı, değerli taşlarla süslü tüy demetine ne ad verilir?', 'Sorguç', ['Püskül', 'Kavuk', 'Hotoz'], 'Sorguç çoğunlukla balıkçıl ya da devekuşu tüyünden yapılır, mücevherli bir yuvaya takılırdı; rütbe ve gücün simgesiydi.'),
  ('Osmanlı\'da sokakta pabucun içine giyilen, ince ve yumuşak deriden yapılmış çorap biçimindeki hafif ayakkabıya ne ad verilir?', 'Mest', ['Çarık', 'Postal', 'Terlik'], 'Mest ev içinde tek başına, dışarıda ise üstüne pabuç ya da çedik giyilerek kullanılırdı; abdest alırken mestin üstüne mesh edilebilmesi pratiklik sağlardı.'),
  ('Osmanlı sarayında en değerli sayılan ve padişahların önemli kişilere armağan ettiği kürk hangi hayvandan elde edilirdi?', 'Samur', ['Tavşan', 'Kuzu', 'Sincap'], 'Samur kürkü Rusya\'dan getirilen çok pahalı bir kürktü; samur kaftan giymek yüksek rütbe ve saygınlık göstergesiydi.'),
  ('Bursa ve İstanbul\'da dokunan, ipek zemin üzerine altın ve gümüş sırma ile iri desenler işlenen ağır Osmanlı saray kumaşı hangisidir?', 'Kemha', ['Bürümcük', 'Atlas', 'Patiska'], 'Kemha, Osmanlı kaftanlarında en çok kullanılan değerli ipeklilerdendir; desenleri ek atkı iplikleriyle dokunurdu.'),
  ('Saten örgüyle dokunan, parlak yüzeyli, desensiz Osmanlı ipek kumaşına ne ad verilir?', 'Atlas', ['Çatma', 'Kemha', 'Bürümcük'], 'Atlas, saten örgüsü sayesinde parlak ve kaygan bir yüzeye sahip ipek kumaştır; entari ve kaftanlarda kullanılırdı.'),
  ('Ham ipekten dokunan, yüzeyi kendiliğinden ince kırışıklarla kaplı, hafif ve geleneksel kumaşa ne ad verilir?', 'Bürümcük', ['Kemha', 'Seraser', 'Kaşe'], 'Bürümcük, yüksek bükümlü ham ipek ipliklerin dokuma sonrasında büzülmesiyle kıvırcık bir yüzey kazanır; gömlek ve örtülerde kullanılır.'),
  ('1934\'te kabul edilen \'Bazı Kisvelerin Giyilemeyeceğine Dair Kanun\' din adamlarının dinî kıyafetleri için ne öngörmüştür?', 'Yalnız ibadet yerlerinde ve ayinlerde giyilmesini', ['Her yerde zorunlu olarak giyilmesini', 'Yalnız resmî bayramlarda giyilmesini', 'Tümüyle ve her yerde, ibadethaneler dâhil yasaklanmasını'], 'Kanuna göre hangi dinden olursa olsun din adamları dinî kıyafetlerini ibadethane ve ayinler dışında giyemez; her dinden bir temsilciye istisna tanınmıştır.'),
  ('Atatürk\'ün 1937\'de bizzat açılışını yaptığı Sümerbank basma fabrikası hangi ilçededir?', 'Nazilli', ['Ereğli', 'Bakırköy', 'Malatya'], 'Nazilli Basma Fabrikası 1937\'de açılmış, çevresinde lojman, okul ve sosyal tesislerle bir yaşam alanı oluşturmuştur.'),
  ('II. Mahmud döneminde orduya fes üretmek için İstanbul\'da kurulan, sonradan yünlü kumaş fabrikasına dönüşen ve bugün kültür merkezi olarak kullanılan tesis hangisidir?', 'Feshane', ['Tophane', 'Darphane', 'Tersane'], 'Feshane 19. yüzyıl Osmanlı sanayileşmesinin ilk örneklerindendir; Haliç kıyısındaki yapı bugün etkinlik ve kültür merkezidir.'),
  ('Yanlardan boydan boya yırtmaçlı olduğu için önde iki, arkada bir parça olmak üzere ayrı etekler gibi açılan geleneksel Anadolu kadın entarisine ne ad verilir?', 'Üç etek', ['Bindallı', 'Ehram', 'Yelek'], 'Üç etek entari kadın giyiminin temel parçasıdır; ön etekler beldeki kuşağa sıkıştırılarak iş yaparken kolaylık sağlanırdı.'),
  ('Anadolu\'da erkeklerin cepken ya da yelek altına giydiği, yakasız ya da dik yakalı, uzun kollu geleneksel gömleğe ne ad verilir?', 'Mintan', ['Zıbın', 'Ferace', 'Hırka'], 'Mintan pamuklu ya da ipekli kumaştan dikilen, geleneksel erkek giyiminin iç katını oluşturan gömlektir.'),
  ('Doğu Karadeniz\'de erkeklerin başına sardığı ya da boynuna doladığı, genellikle siyah renkli ve uçları püsküllü örtüye ne ad verilir?', 'Poşu', ['Kavuk', 'Fes', 'Külah'], 'Poşu Karadeniz erkek giyiminin simgelerinden biridir; horon kıyafetinin de tamamlayıcı parçasıdır.'),
  ('Geçmişte askerlerin ve köylülerin bacaklarını soğuk ve çamurdan korumak için ayak bileğinden dize kadar sardığı uzun sargı bezine ne ad verilir?', 'Dolak', ['Kuşak', 'Yazma', 'Peştamal'], 'Dolak, sarmal biçimde bacağa dolanan uzun bir yün ya da kumaş şerittir; Birinci Dünya Savaşı askerlerinin giyiminde de yaygındı.'),
  ('Altında iki yüksek tahta diş bulunan ve yürürken tak tak ses çıkaran geleneksel Japon sandaletine ne ad verilir?', 'Geta', ['Tabi', 'Obi', 'Zori'], 'Geta yükseltilmiş tabanı sayesinde giysiyi çamur ve sudan korur; zori ise düz tabanlı bir sandalettir.'),
  ('Japonya\'da kimono giyilirken sağ yakanın sol yakanın üzerine kapatılmasından özenle kaçınılır. Bunun nedeni nedir?', 'Bu biçimin ölülere uygulanması', ['Bu biçimin yalnız erkeklere ayrılması', 'Bu biçimin İmparatora özgü olması', 'Bu biçimde kuşağın bağlanamaması'], 'Kadın ve erkek herkes kimononun sol tarafını sağın üzerine kapatır; tersi yalnız ölülerin giydirilmesinde uygulanır.'),
  ('1920\'lerde Şanghay\'da modernleşen, yüksek yakalı, vücuda oturan ve yanları yırtmaçlı Çin kadın elbisesine ne ad verilir?', 'Qipao', ['Hanbok', 'Ao dai', 'Kimono'], 'Qipao (Kantonca cheongsam) Mançu giysilerinden gelişmiş, 20. yüzyılda modern Çinli kadının simgesi olmuştur.'),
  ('Fas\'ta ve Mağrip\'te kadın ve erkeklerin giydiği, kapüşonlu, uzun kollu ve bol dış giysiye ne ad verilir?', 'Cellabiye', ['Kimono', 'Gho', 'Sarong'], 'Cellabiye (djellaba) yünlü ya da pamuklu olabilir; kapüşonu güneş, rüzgâr ve soğuğa karşı koruma sağlar.'),
  ('Arap Yarımadası\'nda erkeklerin giydiği, ayak bileğine kadar uzanan ve çoğunlukla beyaz olan uzun entariye ne ad verilir?', 'Dişdaşa', ['Cellabiye', 'Hanbok', 'Deel'], 'Dişdaşa (thobe) sıcak iklimde güneşi yansıtıp serin tutması için genellikle beyaz ve açık renkli kumaştan dikilir.'),
  ('Malay Takımadaları\'nda ve Pasifik adalarında bele sarılarak etek gibi giyilen tek parça kumaşa ne ad verilir?', 'Sarong', ['Obi', 'Gho', 'Deel'], 'Sarong kadın ve erkekler tarafından giyilir; sıcak ve nemli iklimde rahat ve serin olduğu için yaygındır.'),
  ('Bizans İmparatoru I. Justinianus döneminde ipekböceği yumurtalarının Bizans\'a getirilmesi kaynaklarda nasıl anlatılır?', 'Keşişlerin oyuk bastonlarda kaçırmasıyla', ['Bir Çin prensesinin çeyiziyle gönderilmesiyle', 'Sasanilerle yapılan antlaşmayla satın alınmasıyla', 'Bizans donanmasının Çin limanlarını almasıyla'], 'Prokopios\'un anlattığına göre keşişler yumurtaları bastonların içine saklayarak getirmiş; böylece Bizans kendi ipeğini üretmeye başlamıştır.'),
  ('Roma\'da İmparator Tiberius döneminde erkeklerin ipek giysi giymesinin yasaklanmasında hangi düşünce etkili olmuştur?', 'İpeğin kadınsı ve savurgan sayılması', ['İpeğin askerî üniformalara ayrılması', 'İpeğin yangına yol açtığının düşünülmesi', 'İpeğin pagan rahiplere özgü olması'], 'Romalı ahlakçılar Doğu\'dan gelen pahalı ve ince ipeği aşırı lüks ve erkeklere yakışmaz bulmuş; senato bu yüzden erkeklere ipeği yasaklamıştır.'),
  ('İpek üretiminde kozaların içindeki kelebek çıkmadan haşlanmasının ya da buharlanmasının nedeni nedir?', 'Kelebeğin kozayı delmesini önlemek', ['Kozanın rengini beyazlatmak', 'İpliğe parlaklık kazandırmak', 'Kozayı daha ağır göstermek'], 'Kelebek kozadan çıkarken salgıladığı sıvıyla bir delik açar; bu durumda uzun, kesintisiz ipek lifi kısa parçalara bölünür.'),
  ('James Hargreaves\'in 1760\'larda geliştirdiği \'spinning jenny\' adlı makinenin getirdiği temel yenilik nedir?', 'Bir işçinin aynı anda birçok iğ çalıştırması', ['Dokumanın buhar gücüyle yapılması', 'Pamuğun tohumdan makineyle ayrılması', 'Desenlerin delikli kartlarla dokunması'], 'Spinning jenny ile tek bir işçi başlangıçta sekiz, sonra çok daha fazla iği aynı anda çalıştırabildi; bu, eğirmede verimi büyük ölçüde artırdı.'),
  ('Su gücüyle çalışan iplik makinesini geliştirip 1771\'de Cromford\'da ilk büyük iplik fabrikalarından birini kuran ve fabrika sisteminin öncüsü sayılan kişi kimdir?', 'Richard Arkwright', ['Samuel Crompton', 'James Watt', 'John Kay'], 'Arkwright\'ın su çerçevesi sağlam çözgü ipliği üretiyordu; Cromford\'daki tesisi işçilerin vardiyalı çalıştığı modern fabrikanın ilk örneklerindendir.'),
  ('Eli Whitney\'nin 1793\'te geliştirdiği çırçır makinesinin ABD\'nin güney eyaletlerinde yol açtığı önemli bir sonuç nedir?', 'Köle emeğine dayalı plantasyonların büyümesi', ['Pamuk tarımının tümüyle terk edilmesi', 'Köleliğin hemen kaldırılması', 'Yünün pamuğun yerini alması'], 'Çırçır pamuğun işlenmesini çok hızlandırdı; pamuk yetiştirmek çok kârlı hâle gelince köle emeğine dayalı plantasyonlar genişledi.'),
  ('1811-1816 yıllarında İngiltere\'de işlerini tehdit ettiğini düşündükleri tekstil makinelerini kıran işçilere ne ad verilir?', 'Ludditler', ['Çartistler', 'Jakobenler', 'Levellerlar'], 'Ludditler efsanevi bir \'Ned Ludd\' adını kullanarak örme ve dokuma makinelerini kırdı; ad bugün teknoloji karşıtları için de kullanılır.'),
  ('1846\'da kilitli dikiş yapan dikiş makinesinin ABD\'deki patentini alan ve sonradan patent davalarıyla tanınan mucit kimdir?', 'Elias Howe', ['Isaac Singer', 'Walter Hunt', 'Thomas Edison'], 'Howe\'un patenti ucunda delik bulunan iğne ile mekiğin birlikte çalıştığı kilitli dikiş ilkesini kapsıyordu; sonraki üreticiler ona lisans ücreti ödemek zorunda kaldı.'),
  ('Mahatma Gandhi\'nin Hindistan\'ın bağımsızlık hareketinde çıkrığı bir simge olarak kullanmasının amacı neydi?', 'Yerli el dokumasını desteklemek', ['Hint pamuğunu Avrupa\'ya ihraç etmek', 'Fabrikaların sayısını artırmak', 'Hint askerlerine üniforma dikmek'], 'Gandhi herkesin kendi ipliğini eğirip khadi denen yerli kumaşı giymesini önerdi; bu, ekonomik bağımsızlığın ve İngiliz mallarını boykotun simgesiydi.'),
  ('Bir doğal boyacı, Meksika\'dan gelen ve kaktüs üzerinde yaşayan kurutulmuş küçük böcekleri öğütüp yünü parlak kırmızıya boyuyor. Kullandığı boya hangisidir?', 'Koşnil', ['İndigo', 'Safran', 'Alizarin'], 'Koşnil böceklerinin kurutulmasıyla elde edilen karmin, Avrupa\'da çok değerli bir kırmızı boya ve ticaret malı oldu.'),
  ('Doğal indigo ticaretini 20. yüzyılın başında büyük ölçüde sona erdiren gelişme hangisidir?', 'Sentetik indigonun fabrikada üretilmesi', ['İndigo bitkisinin bir salgınla yok olması', 'Mavi rengin moda dışı kalması', 'İndigo ticaretinin yasaklanması'], 'Sentetik indigo 1897\'den itibaren endüstriyel olarak üretilmeye başlandı; ucuz ve standart olduğu için Hindistan\'daki indigo tarımını kısa sürede geriletti.'),
  ('Askerî üniformalarla özdeşleşen \'haki\' renginin adı Farsça ve Hintçede hangi anlama gelen bir sözcükten gelir?', 'Toz, toprak', ['Zeytin dalı', 'Kurumuş sarı ot', 'Çöl kumu'], 'Haki, \'toz rengi\' demektir; 19. yüzyılda Hindistan\'daki İngiliz birlikleri göze batmamak için bu renkte giysiler kullanmaya başladı.'),
  ('Avrupa\'da 13. yüzyıldan itibaren ilik ile düğmenin birlikte yaygın biçimde kullanılmaya başlaması giyimi nasıl etkilemiştir?', 'Bedene sıkıca oturan giysileri mümkün kıldı', ['Giysilerin tümüyle dikişsiz yapılmasını sağladı', 'Kürk kullanımını tamamen sona erdirdi', 'Giysilerin yalnız arkadan kapanmasına yol açtı'], 'Öncesinde giysiler bağcık, iğne ya da bol kesimle giyiliyordu; iliğe geçen düğmeler kolların ve gövdenin vücuda göre daraltılmasını kolaylaştırdı.'),
  ('Batı giyim geleneğinde kadın gömlek ve bluzlarında düğmeler genellikle hangi tarafta bulunur?', 'Giyen kişinin sol tarafında', ['Giyen kişinin sağ tarafında', 'Her zaman arkada', 'Her zaman tam ortada, gizli patın altında'], 'Erkek gömleklerinde düğmeler giyenin sağında, kadın giysilerinde solunda yer alır; bu gelenek yüzyıllardır sürmektedir.'),
  ('Kayan kilit anlamında \'zipper\' sözcüğü İngilizceye 1920\'lerde hangi ürün için kullanılan ticari addan yerleşmiştir?', 'Fermuarlı kauçuk galoş çizmeler', ['Asker çantaları', 'Uçak pilotlarının koltuk kılıfları', 'Kadın el çantaları'], 'Bir lastik şirketi fermuarla kapanan galoşlarını \'Zipper Boots\' adıyla satmış; ad zamanla kilidin kendisine verilmiştir.'),
  ('Bakım etiketlerinde ütü simgesinin içindeki noktaların sayısı neyi gösterir?', 'En yüksek ütü sıcaklığını', ['Ütülenecek kez sayısını', 'Kumaştaki lif türü sayısını', 'Buhar kullanılacak süreyi'], 'Bir nokta düşük (yaklaşık 110 °C), iki nokta orta (150 °C), üç nokta yüksek (200 °C) ütü sıcaklığını anlatır.'),
  ('Sentetik bir bluzun etiketindeki ütü simgesinde yalnız bir nokta bulunuyor. Bu bluz için ütü nasıl ayarlanmalıdır?', 'En düşük sıcaklık ayarına', ['En yüksek sıcaklık ayarına', 'Orta sıcaklıkta bol buhara', 'Pamuk ve keten ayarına'], 'Tek nokta yaklaşık 110 °C\'yi geçmeyen düşük ısıyı anlatır; naylon ve akrilik gibi lifler yüksek ısıda erir ya da parlar.'),
  ('Bir kazağın etiketinde kare içinde bir daire ve bu dairenin üzerinde bir çarpı işareti bulunuyor. Bu kazak nasıl kurutulmamalıdır?', 'Tamburlu kurutma makinesinde', ['Askıda asılarak', 'Düz bir yüzeye serilerek', 'Gölgede kendi hâlinde'], 'Kare kurutmayı, içindeki daire tamburlu kurutma makinesini simgeler; simgenin üzerindeki çarpı bu yöntemin kullanılmaması gerektiğini bildirir.'),
  ('Bakım etiketindeki tek daire simgesinin içinde yer alan P ya da F harfleri neyi bildirir?', 'Kullanılabilecek çözücü türünü', ['Kumaşın polyester ya da flanel olduğunu', 'Giysinin üretildiği ülkeyi', 'Ütünün buhar düzeyini'], 'Daire kuru temizlemenin simgesidir; harfler temizleyicinin hangi tür çözücüyü kullanabileceğini gösteren profesyonel bilgilerdir.'),
  ('Bir kazağın etiketindeki yıkama leğeni simgesinin altında iki yatay çizgi bulunuyor. Bu kazak nasıl yıkanmalıdır?', 'Çok hassas (yünlü) programda', ['Kaynatarak çok yüksek ısıda', 'Normal pamuklu programda', 'Yalnız kuru temizlemede'], 'Leğenin altındaki tek çizgi hassas, iki çizgi çok hassas yıkamayı anlatır; düşük devir ve az mekanik hareket gerektirir.'),
  ('Bakım etiketinde kare içinde tek bir yatay çizgi bulunan simge ne anlatır?', 'Düz bir yüzeye serilerek kurutulmalı', ['Askıya asılarak kurutulmalıdır', 'Kurutma makinesine konmalıdır', 'Gölgede değil güneşte kurutulmalıdır'], 'Yatay çizgi giysinin düz serilerek kurutulmasını ister; özellikle yün kazakların asılınca uzayıp biçim bozmasını önler.'),
  ('Nevresim ve çarşaflarda belirtilen \'iplik sayısı\' (thread count) neyi gösterir?', 'Bir inç karedeki iplik toplamını', ['Bir metredeki dikiş adımı sayısını', 'Kumaşta kullanılan renk sayısını', 'İpliğin kaç kat büküldüğünü'], 'İplik sayısı arttıkça kumaş genellikle daha sık ve pürüzsüz olur; ancak kaliteyi lif ve iplik türü de belirler.'),
  ('Bir müşteri iki ipek yastık kılıfından daha ağır ve dayanıklı olanını seçmek istiyor. Etiketlerde hangi birimle verilen değeri karşılaştırmalıdır?', 'Momme', ['Denye', 'Tex', 'Arşın'], 'Momme değeri yükseldikçe ipek kumaş daha ağır ve dayanıklıdır; ipek nevresim ve fularlarda sıkça belirtilir.'),
  ('Yün liflerinin inceliği uluslararası ticarette genellikle hangi birimle ifade edilir?', 'Mikrometre', ['Milimetre', 'Denye', 'Momme'], 'Yün lif çapı mikrometre (mikron) ile ölçülür; ince merinos yünü genellikle 20 mikronun altındadır ve tene batmaz.'),
  ('Denye 9000 metre, tex ise 1000 metre ipliğin gram ağırlığıdır. Buna göre 20 denyelik bir iplik yaklaşık kaç tex\'tir?', '2,2', ['180', '20', '0,45'], 'Aynı uzunluk için 9000/1000 = 9 kat fark vardır: tex = denye / 9 = 20 / 9 ≈ 2,2.'),
  ('Ucuz ve kaba dokulu pamuklu bez anlamında kullanılan \'kaliko\' adı hangi Hint liman kentinin adından gelir?', 'Kalikut', ['Kalküta', 'Bombay', 'Madras'], 'Avrupalı tüccarlar Malabar kıyısındaki Kalikut limanından aldıkları pamuklu kumaşları bu kentin adıyla anmıştır.'),
  ('Örme kumaş anlamındaki \'jarse\' sözcüğü hangi yerin adından gelir?', 'Manş\'taki Jersey Adası\'ndan', ['İskoçya\'daki Jedburgh kasabası', 'Fransa\'daki Jargeau köyü', 'ABD\'deki New Jersey eyaleti'], 'Jersey Adası\'nda örülen yün balıkçı kazakları yüzyıllarca ünlüydü; adanın adı zamanla örme kumaşın genel adı oldu.'),
  ('Kalın ve sağlam bez anlamındaki \'kanvas\' sözcüğünün kökü hangi bitkinin Latince adına dayanır?', 'Kenevir', ['Keten', 'Pamuk', 'Jüt bitkisi'], 'Kanvas Latince \'cannabis\' (kenevir) sözcüğünden gelir; bu kumaş başlangıçta kenevir liflerinden dokunurdu.'),
  ('İç çamaşırı anlamındaki \'lanjeri\' sözcüğünün kökü olan Fransızca \'linge\' başlangıçta neyi anlatıyordu?', 'Ketenden yapılan çamaşırı', ['İpekten yapılan gecelikleri', 'Dantel süslemeleri', 'Korse balenlerini'], 'Linge, Latince \'linum\' (keten) sözcüğünden gelir; iç giysiler eskiden çoğunlukla ketenden yapıldığı için bu ad verilmiştir.'),
  ('Dantel sözcüğü Fransızcada hangi anlama gelen bir sözcükten türemiştir?', 'Küçük diş', ['Örümcek ağı', 'Kar tanesi', 'Balık ağı'], 'Fransızca \'dentelle\' küçük diş demektir; dantel kenarlarının diş diş görünümüne gönderme yapar.'),
  ('Birinci Dünya Savaşı\'nda Fransız ordusunda kamuflaj boyalarını ve desenlerini geliştiren birimlerde başlıca hangi meslekten kişiler görev almıştır?', 'Ressamlar ve sahne dekoratörleri', ['Kimyagerler ve eczacılar', 'Terziler ve kunduracılar', 'Mimarlar ve köprü inşaat ustaları'], 'Kamuflaj birimlerinde çalışan \'camoufleur\'lerin çoğu sanatçıydı; renk ve biçim bilgileriyle görüntüyü bozan desenler tasarladılar.'),
  ('Lacivert ve beyaz yatay çizgili Breton tişörtü 1858\'de hangi kurumun resmî üniformasının parçası olarak kabul edilmiştir?', 'Fransız donanmasının', ['İngiliz kraliyet muhafızlarının', 'Fransız demiryollarının', 'İtalyan jandarmasının'], 'Çizgili desenin denize düşen bir denizcinin dalgalar arasında daha kolay görülmesini sağladığı anlatılır; Chanel\'le birlikte modaya da girmiştir.'),
  ('Tişört, 20. yüzyılın başında iç giysi olarak ilk kez hangi kurumun resmî donanımına girmiştir?', 'ABD Donanması', ['Fransız Yabancı Lejyonu', 'İngiliz Kraliyet Hava Kuvvetleri', 'Osmanlı Bahriyesi'], 'ABD Donanması 1913\'te kısa kollu beyaz iç gömleğini standart donanıma aldı; savaş sonrası bu giysi sivil yaşamda dış giysiye dönüştü.'),
  ('Yeniçerilerin başlarına giydiği, arkası sırta doğru sarkan beyaz keçe başlığa ne ad verilir?', 'Börk', ['Fes', 'Kavuk', 'Sarık'], 'Yeniçeri börkü (üsküf) Hacı Bektaş Veli\'nin hırkasının yeninden esinlendiği anlatılan ve arkaya sarkan bir başlıktır.'),
  ('2013\'te Bangladeş\'te çok sayıda hazır giyim atölyesinin bulunduğu bir binanın çökmesiyle binden fazla işçinin öldüğü ve moda endüstrisindeki çalışma koşullarını dünya gündemine taşıyan felaket hangisidir?', 'Rana Plaza', ['Bhopal', 'Triangle Shirtwaist', 'Seveso'], 'Rana Plaza binasında çatlaklar görüldüğü hâlde işçiler çalışmaya zorlanmıştı; felaket tedarik zincirinde denetim ve işçi güvenliği tartışmalarını başlattı.'),
  ('Moda terminolojisinde \'vintage\' ile \'retro\' arasındaki fark hangisidir?', 'Vintage eskiden kalma özgün parça, retro eskiyi taklit eden yeni üretimdir', ['Vintage yalnız kadın giysisidir; retro yalnız erkek giysisidir', 'Vintage elde, retro makinede dikilmiş giysidir', 'İkisi de yalnız 1980\'lerden kalma giysileri anlatır'], 'Vintage bir parça geçmiş bir dönemde gerçekten üretilmiştir; retro ise eski bir dönemin üslubunu bugün yeniden üretir.'),
  ('Günümüzde deri tabaklamada en yaygın kullanılan ve atık sularda çevre sorunlarına yol açabilen kimyasal hangisidir?', 'Krom tuzları', ['Sofra tuzu', 'Karbonat', 'Arap zamkı çözeltisi'], 'Krom tabaklama hızlı ve ucuzdur, ancak denetimsiz atık suları toprak ve suda kirliliğe yol açabilir.'),
  ('Bitkisel tabaklamada deriyi çürümez ve dayanıklı hâle getiren tanen maddesi geleneksel olarak hangi kaynaklardan sağlanır?', 'Meşe palamudu ve ağaç kabuğu', ['Balık yağı ve tuzdan', 'Kireç ve küllerden', 'Pamuk çiğidinden'], 'Tanen, deri proteinine bağlanarak onu çürümeye dayanıklı hâle getirir; meşe palamudu, sumak ve kestane kabuğu geleneksel tanen kaynaklarıdır.'),
  ('Eşofman sözcüğünün kökü olan Fransızca \'échauffement\' hangi anlama gelir?', 'Isınma', ['Koşu', 'Yarış', 'Terleme'], 'Eşofman, sporcuların ısınma sırasında giydiği giysidir; Türkçeye bu anlamıyla Fransızcadan geçmiştir.'),
  ('Eski korselerin sertliğini sağlayan \'balen\' adlı esnek çubuklar başlangıçta neyden yapılırdı?', 'Balinaların süzgeç plakalarından', ['Çelik tellerden', 'Bambu kamışlarından', 'Fil dişinden'], 'Balen, bazı balinaların ağzında besinleri süzen boynuzsu plakalardır; esnek ve dayanıklı olduğu için korse ve şemsiyelerde kullanılırdı.'),
  ('Birinci Dünya Savaşı sırasında ABD\'de kadınlardan korse satın almamalarının istenmesinin nedeni neydi?', 'Korse çeliğinin savaşa gerekmesi', ['Korselerin askerlik muayenesini zorlaştırması', 'Korse kumaşlarının üniformaya ayrılması', 'Korselerin ithalatının durması'], 'Savaş yönetimi kadınlardan korse almamalarını istemiş, böylece binlerce ton metalin silah ve gemi yapımına aktarıldığı anlatılır.'),
  ('1960\'larda külotlu çorabın hızla yaygınlaşmasında hangi moda gelişmesi etkili olmuştur?', 'Mini eteğin yaygınlaşması', ['Uzun maksi eteklerin dönüşü', 'Kadın smokininin çıkışı', 'Kot pantolonun yasaklanması'], 'Mini etekler jartiyerli çorapların bağlantı yerlerini açıkta bırakıyordu; tek parça külotlu çorap bu sorunu çözdü.'),
  ('Sosyolog Georg Simmel\'in görüşlerine dayandırılan \'damlama (trickle-down) kuramı\'na göre moda nasıl yayılır?', 'Üst sınıflardan alt sınıflara taklitle', ['Sokaktan podyuma doğru aşağıdan yukarıya', 'Tüm sınıflarda aynı anda kendiliğinden', 'Yalnız devlet kararlarıyla yukarıdan'], 'Kurama göre üst sınıflar ayırt edici olmak için yeni bir moda benimser, alt sınıflar onu taklit edince üst sınıf yeniden başka bir modaya yönelir.'),
  ('Punk ve hip-hop giyiminin önce sokaklarda doğup sonra lüks moda evlerinin podyumlarına taşınması hangi yayılma biçimine örnektir?', 'Aşağıdan yukarıya yayılım', ['Damlama kuramı', 'Lüks yasaları', 'Kapsül gardırop anlayışı'], 'Bu yaklaşımda trendler gençlik alt kültürlerinde ve sokakta başlar, tasarımcılar onları yorumlayarak yüksek modaya taşır.'),
  ('Bir trendin yaşam döngüsünde, ürünün kitleler tarafından en yaygın biçimde benimsendiği ve her mağazada bulunduğu evreye ne ad verilir?', 'Doruk evresi', ['Giriş evresi', 'Terk evresi', 'Gerileme evresi'], 'Moda döngüsü giriş, yükseliş, doruk, düşüş ve terk evrelerinden oluşur; doruk evresinde ürün kitlesel olarak satılır.'),
  ('2010\'larda ortaya çıkan, sıradan ve dikkat çekmeyen temel giysileri bilinçli olarak tercih etmeyi anlatan moda terimi hangisidir?', 'Normcore', ['Grunge', 'Glam rock', 'Barokko'], 'Normcore, \'normal\' ve \'hardcore\' sözcüklerinin birleşimidir; sade tişört, düz kot ve spor ayakkabı gibi sıradan parçaları öne çıkarır.'),
  ('İktisatçı Thorstein Veblen\'in \'gösterişçi tüketim\' kavramı giyim alanında en çok neyi açıklar?', 'Pahalı giysilerle statü gösterilmesini', ['Giysilerin yalnız ihtiyaç için alınmasını', 'Ucuz giysilerin daha çok satılmasını', 'Giysi üretiminin makineleşmesini'], 'Veblen\'e göre zenginler servetlerini göstermek için pahalı ve işlevsiz lüks mallar tüketir; moda bunun en görünür alanlarındandır.'),
  ('1960\'larda İngiltere\'de dar kesim İtalyan takımları, askerî parkaları ve Vespa motosikletleriyle tanınan genç alt kültür hangisidir?', 'Modlar', ['Rockerlar', 'Hippiler', 'Punklar'], 'Modlar şık ve özenli giyimleriyle, deri ceketli ve motosikletli Rockerlarla rekabetleriyle anılır.'),
  ('1950\'lerde İngiltere\'de Edward dönemi giyiminden esinlenen uzun ceketler, dar pantolonlar ve kalın tabanlı ayakkabılar giyen gençlere ne ad verilirdi?', 'Teddy Boys', ['Modlar', 'Dandyler', 'Beatnikler'], 'Teddy adı Kral VII. Edward\'ın kısaltılmış adından gelir; bu gençler Edward dönemi terziliğini kendi tarzlarıyla yorumladılar.'),
  ('Bir yüzü şardonla hafifçe tüylendirilmiş, kışlık pijama ve geceliklerde kullanılan yumuşak pamuklu kumaşa ne ad verilir?', 'Pazen', ['Organze', 'Saten', 'Tafta'], 'Pazen pamuktan dokunur ve tüylendirilir; sıcak ve yumuşak olduğu için kış aylarında ev giysilerinde tercih edilir.'),
  ('Havlu kumaşının suyu iyi emmesini sağlayan yapı özelliği hangisidir?', 'İlmekli havların temas alanını artırması', ['Kumaşın su itici apre içermesi', 'Saten örgüyle dokunması', 'Sentetik liflerden yapılması'], 'Havludaki çok sayıda ilmek, suyla temas eden yüzeyi büyük ölçüde artırır; pamuk lifi de suyu iyi emer.'),
  ('Süet sözcüğü, bu deriden yapılan eldivenlerin Fransızcadaki adlandırmasında geçen hangi ülkenin adından gelir?', 'İsveç', ['İsviçre', 'Danimarka', 'İspanya'], 'Fransızca \'gants de Suède\' (İsveç eldivenleri) ifadesindeki \'Suède\' sözcüğü zamanla bu tür derinin adı olmuştur.'),
  ('Süetten farklı olarak derinin dış (hav) yüzünün hafifçe zımparalanmasıyla elde edilen, daha dayanıklı kadifemsi deri hangisidir?', 'Nubuk', ['Rugan', 'Kösele', 'Napa'], 'Nubuk derinin dayanıklı dış yüzünden yapıldığı için süete göre daha sağlamdır; görünümü ise benzer biçimde kadifemsidir.'),
  ('Ahilik geleneğinde debbağların (deri tabaklayanların) piri olarak kabul edilen kişi kimdir?', 'Ahi Evran', ['Hacı Bektaş Veli', 'Yunus Emre', 'Mevlânâ'], 'Ahi Evran Kırşehir\'de yaşamış, debbağlık yaptığı anlatılan ve Ahi teşkilatının kurucusu sayılan kişidir.'),
  ('Yıpranmış ceketini atmak yerine Japon geleneğine uygun biçimde lacivert kumaş üzerine beyaz iplikle sık geometrik ön dikişler atarak güçlendiren birinin kullandığı teknik hangisidir?', 'Sashiko', ['Shibori', 'Origami', 'Kintsugi'], 'Sashiko \'küçük batırmalar\' demektir; köylülerin kat kat kumaşları birleştirip sağlamlaştırmasından doğmuştur.'),
  ('Kuzey Hindistan\'da gelinlerin sıkça giydiği, uzun ve işlemeli bir etek, kısa bir bluz ve şaldan oluşan giysiye ne ad verilir?', 'Lehenga choli', ['Shalwar kameez', 'Dhoti kurta', 'Sherwani'], 'Lehenga choli düğünlerde genellikle kırmızı ve altın işlemeli olarak tercih edilir; sherwani ise damadın uzun ceketidir.'),
  ('1981\'de Galler Prensesi Diana\'nın düğününde giydiği gelinliğin en çok konuşulan özelliği hangisidir?', 'Yaklaşık 7,6 metrelik kuyruğu', ['Tümüyle siyah dantelden yapılması', 'Diz üstünde bitmesi', 'Pantolonlu olması'], 'Diana\'nın ipek tafta gelinliğinin 25 fit (yaklaşık 7,6 m) uzunluğundaki kuyruğu, St Paul Katedrali\'nin koridoru boyunca uzanmıştı.'),
  ('Mezuniyet törenlerinde giyilen cüppelerin kökeni hangi geleneğe dayanır?', 'Orta Çağ akademisyenlerinin cüppelerine', ['Roma lejyonerlerinin pelerinlerine', 'Osmanlı yeniçerilerinin üniformalarına', 'Rönesans tüccarlarının kürklerine'], 'Orta Çağ Avrupa\'sında üniversiteler din kurumlarıyla iç içeydi; hoca ve öğrenciler ısınmak için de uzun cüppeler giyerdi. Gelenek bugün tören giysisi olarak sürer.'),
  ('İngiltere\'de mahkemelerde yargıç ve avukatların geleneksel olarak taktığı perukalar hangi malzemeden yapılır?', 'At kılından', ['İnsan saçından', 'Koyun yününden', 'Keten ipliğinden'], 'İngiliz hukuk perukaları 17. yüzyıl modasının kalıntısıdır; beyaz ya da kırık beyaz at kılından el işçiliğiyle yapılır.'),
  ('Mutfak şeflerinin taktığı uzun, beyaz ve pilili şapkanın Fransızca adı nedir?', 'Toque', ['Béret', 'Képi', 'Chapeau'], 'Toque blanche (beyaz toka) şeflerin simgesidir; uzunluğu geleneksel olarak mutfaktaki hiyerarşiyle ilişkilendirilmiştir.'),
  ('Ameliyathanelerde cerrah giysilerinin beyaz yerine çoğunlukla yeşil ya da mavi olmasının başlıca nedeni nedir?', 'Kırmızının yarattığı ard görüntüleri azaltmak', ['Bu renklerin daha ucuz boyanması', 'Kanın bu renklerde hiç görünmemesi', 'Hastaların bu renklerden hoşlanması'], 'Uzun süre kırmızı kana bakan göz beyaz yüzeyde yeşil ard görüntüler görür; yeşil-mavi giysiler bu yanılsamayı azaltır ve göz yorgunluğunu düşürür.'),
  ('Yol çalışanlarının giydiği yeleklerdeki gümüş renkli şeritlerin işlevi nedir?', 'Far ışığını geri yansıtıp görünür kılmak', ['Güneş ışınlarını yansıtıp serinlik sağlamak', 'Yeleğin yırtılmasını önlemek', 'Kişinin rütbesini göstermek'], 'Retroreflektif şeritlerdeki minik cam boncuklar ya da prizmalar ışığı geldiği yöne geri yansıtır; böylece sürücü çalışanı uzaktan görür.'),
  ('Japonya\'da kız öğrenci okul üniformalarında yaygın olan ve \'sērā fuku\' diye anılan tarz hangi giysiden esinlenmiştir?', 'Denizci giysisi', ['Samuray zırhı', 'Hemşire önlüğü ve başlığı', 'Pilot ceketi'], 'Sērā fuku \'denizci kıyafeti\' demektir; 1920\'lerde Avrupa denizci giysilerinden esinlenerek okul üniforması olarak benimsenmiştir.'),
  ('Havayolu pilotlarının kol ve omuzlarındaki şeritlerle rütbe göstermesi geleneği hangi alandan alınmıştır?', 'Denizcilikten', ['Demiryolculuktan', 'Polis teşkilatından', 'İtfaiyecilikten'], 'Havacılık ilk dönemlerinde kaptan, yardımcı pilot gibi unvanlarla birlikte şeritli rütbe işaretlerini deniz geleneğinden devralmıştır.'),
  ('19. yüzyılın başında ampir modasında kadınların elde taşıdığı \'retikül\' adlı küçük keselerin yaygınlaşmasının nedeni nedir?', 'İnce elbiselerde cep taşınamaması', ['Paranın ilk kez kâğıt olarak basılması', 'Erkeklerin çanta taşımasının yasaklanması', 'Kadınların ata binmeye başlaması'], 'Önceki dönemlerde kadınlar bol eteklerin altına bağlanan ayrı cepler kullanırdı; ince ampir elbiseler bu cepleri gizleyemeyince eşyalar elde taşınan keselere geçti.'),
  ('Kol saatinin erkekler arasında yaygın bir aksesuar hâline gelmesinde hangi gelişme etkili olmuştur?', 'Birinci Dünya Savaşı\'ndaki askerler', ['Demiryollarının icadı', 'Radyonun yaygınlaşması', 'Olimpiyatların yeniden başlaması'], 'Kol saatleri önce daha çok kadın aksesuarı sayılıyordu; siperlerde cep saatini çıkarmak zor olduğu için askerler kol saatini benimsedi.'),
  ('Hollywood\'da kostüm tasarımcısı olarak sekiz Oscar kazanan, \'Roma Tatili\' ve \'Sabrina\' gibi filmlerin kostümleriyle tanınan tasarımcı kimdir?', 'Edith Head', ['Coco Chanel', 'Elsa Schiaparelli', 'Vera Wang'], 'Edith Head onlarca yıl Paramount ve Universal stüdyolarında çalıştı; kostüm tasarımı alanında en çok Oscar alan kadın olarak anılır.'),
  ('\'Rüzgâr Gibi Geçti\'de Scarlett O\'Hara\'nın evdeki yeşil kadife perdelerden kendine elbise diktirmesi en çok neyi yansıtır?', 'Yoksullukta görünüşü koruma çabasını', ['Dönemin perde modasının giysiye geçmesini', 'Scarlett\'in terzilik eğitimi aldığını', 'Kadifenin o dönemde ucuz olmasını'], 'İç Savaş sonrası her şeyini yitiren Scarlett, varlıklı görünmek için elindeki tek değerli kumaşı kullanır; sahne giyimin toplumsal anlamını gösterir.'),
  ('Tişörtün iç giysi olmaktan çıkıp asi gençliğin simgesi hâline gelmesinde 1950\'lerde hangi oyuncuların filmleri etkili olmuştur?', 'Marlon Brando ve James Dean', ['Charlie Chaplin ve Buster Keaton', 'Fred Astaire ve Gene Kelly', 'Cary Grant ve Gregory Peck'], 'Brando\'nun \'Arzu Tramvayı\' ve Dean\'in \'Asi Gençlik\' filmlerinde giydiği tişörtler bu giysiyi tek başına giyilen bir dış giysiye dönüştürdü.'),
  ('Saçın ön kısmının yukarı ve geriye doğru kabartılarak yapıldığı saç modeli kimin adıyla anılır?', 'Madame de Pompadour', ['Marie Antoinette', 'Joséphine de Beauharnais', 'Madame du Barry'], 'Pompadour saç modeli XV. Louis\'nin gözdesi Madame de Pompadour\'a atfedilir; 1950\'lerde erkek saç modeli olarak da yeniden moda oldu.'),
  ('18. yüzyılda peruklara beyaz ya da kırçıllı bir görünüm vermek için üzerlerine genellikle ne serpilirdi?', 'Nişasta ya da un', ['Tebeşir tozu ve kireç', 'Gümüş tozu', 'Tuz kristalleri'], 'Peruk pudrası genellikle ince öğütülmüş nişasta ya da undan yapılır, bazen parfümle kokulandırılırdı.'),
  ('Psikolog J. C. Flügel\'in \'Büyük Erkek Feragati\' diye adlandırdığı 19. yüzyıl değişimi neyi anlatır?', 'Erkeklerin süsü bırakıp sade, koyu takıma geçmesini', ['Erkeklerin peruk takmaya yeniden başlamasını', 'Kadınların erkek giysilerini benimsemesini', 'Erkeklerin askerlik dışında üniforma giymemesini'], '18. yüzyılda erkek giyimi kadınınki kadar süslüyken 19. yüzyılda erkekler gösterişi kadın giyimine bırakarak sade ve ciddi bir görünüme geçti.'),
  ('19. yüzyılda makinelerle üretilen pamuklu kumaşların ucuzlaması moda üzerinde nasıl bir etki yapmıştır?', 'Modayı geniş kesimlere ulaştırdı', ['Modayı yalnız saraylara özgü hâle getirdi', 'El dokumasını tümüyle değerli kıldı', 'Renkli giysileri ortadan kaldırdı'], 'Ucuz ve desenli pamuklular sayesinde işçi ve orta sınıflar da modaya uygun giysiler edinebilmeye başladı; moda giderek demokratikleşti.'),
  ('Hazır giyimde standart beden ölçülerinin geliştirilmesinde, kısa sürede çok sayıda hazır üniforma üretilmesini gerektiren hangi olay etkili olmuştur?', 'ABD İç Savaşı', ['Fransız Devrimi', 'Kırım Savaşı', 'Yedi Yıl Savaşları'], 'İç Savaş\'ta milyonlarca askere üniforma dikmek için asker ölçüleri toplanmış, bu veriler savaş sonrasında hazır giyim bedenlerinin temeli olmuştur.'),
  ('18. yüzyılın sonlarında çocukların yetişkin giysilerinin küçük kopyaları yerine hareket özgürlüğü veren rahat giysiler giymesini savunan düşünceleriyle etkili olan filozof kimdir?', 'Jean-Jacques Rousseau', ['Immanuel Kant', 'René Descartes', 'John Locke'], 'Rousseau \'Emile\' adlı eserinde çocukların doğal gelişimini kısıtlayan sıkı giysileri eleştirmiş; bu düşünce çocuk giyiminin rahatlamasına katkıda bulunmuştur.'),
  ('Bir kişi \'Pembe her zaman kız çocuklarının, mavi ise erkek çocuklarının rengi olmuştur.\' diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Yanlıştır; bu ayrım 20. yüzyıl ortasında yerleşti', ['Doğrudur; bu ayrım Antik Roma\'dan beri sürmektedir', 'Doğrudur; bu ayrım Orta Çağ\'da yasayla konmuştur', 'Yanlıştır; tarih boyunca tersi bir ayrım hep geçerli olmuştur'], '19. yüzyılda bebekler çoğunlukla beyaz giydirilirdi; 20. yüzyılın başında bazı kaynaklar pembeyi erkeklere önermiş, bugünkü ayrım ancak yüzyılın ortasında kalıcılaştı.'),
  ('Denizli\'nin bir ilçesinde el ve makine tezgâhlarında dokunan, pamuklu havlu ve örtüleriyle ünlü coğrafi işaretli geleneksel bez hangisidir?', 'Buldan bezi', ['Şile bezi', 'Rize bezi', 'Ankara sof kumaşı'], 'Buldan dokumacılığı yüzyıllardır sürer; ince pamuklu bezleri ve tülbentleriyle tanınır.'),
  ('1980\'lerde askerî paraşüt naylonundan yaptığı siyah sırt çantalarıyla lüks modada naylonu yaygınlaştıran İtalyan tasarımcı kimdir?', 'Miuccia Prada', ['Donatella Versace', 'Alberta Ferretti', 'Laura Biagiotti'], 'Prada\'nın naylon çantası, ucuz sayılan bir malzemenin lüks moda nesnesine dönüşmesinin simgesi oldu.'),
  ('Bir alıcı iki kumaşı gözlerini kapatıp elleriyle yoklayarak yumuşaklık, kayganlık ve sertliklerini karşılaştırıyor. Alıcının değerlendirdiği özellik hangisidir?', 'Tutum', ['Döküm', 'Gramaj', 'Haslık'], 'Tutum (tuşe) kumaşın elle değerlendirilen niteliğidir; terbiye işlemleriyle önemli ölçüde değiştirilebilir.'),
  ('Kuru kış günlerinde akrilik bir kazağı çıkarırken çıtırtı duyulması ve küçük kıvılcımlar görülmesinin nedeni nedir?', 'Liflerde statik elektrik birikmesi', ['Kazağın içindeki metal ipliklerin ısınması', 'Kazağın yün lifleriyle kimyasal tepkimesi', 'Odanın havasındaki nemin donması'], 'Sentetik lifler az nem çektiği için elektrik yükünü kolay iletemez; sürtünmeyle biriken yük ani boşalarak kıvılcım ve çıtırtı yaratır.'),
  ('Bir tişörtün etiketinde \'UPF 50+\' ifadesi bulunuyor. Bu ifade neyi anlatır?', 'UV ışınlarının çok büyük bölümünün engellendiğini', ['Tişörtün 50 dereceye kadar yıkanabileceğini', 'Kumaşın yüzde 50\'den fazla pamuk içerdiğini', 'Tişörtün 50 kez yıkamaya dayanıklı olduğunu'], 'UPF (ultraviyole koruma faktörü) kumaşın UV ışınlarına karşı koruma düzeyini gösterir; 50+ en yüksek koruma sınıfıdır.'),
  ('Yün bir kazağın yağmurda bir miktar nem çektiği hâlde hemen ıslak ve soğuk hissettirmemesi nasıl açıklanır?', 'Lifin nemi içine çekip tutması', ['Yünün suyu hiç emmeyip tümüyle itmesi', 'Yünün içindeki havanın suyu buharlaştırması', 'Yün liflerinin elektrik üretmesi'], 'Yün higroskopik bir liftir; nemi lifin iç yapısına alır ve yüzeyi uzun süre kuru hissettirir. Nem tutulurken az miktarda ısı da açığa çıkar.'),
  ('Gömleğin önünde düğme ve iliklerin bulunduğu, iki kat kumaştan oluşan dikey şeride ne ad verilir?', 'Pat', ['Klapa', 'Manşet', 'Vatka'], 'Pat gömleğin önünü güçlendirir; gizli patlı gömleklerde düğmeler bir kumaş katının arkasında kalır.'),
  ('Bir terzi resmî bir ceketin önüne, dışarıdan yalnız ince bir yarık gibi görünen sade bir cep açmak istiyor. Hangi cep türünü uygulamalıdır?', 'Fileto cep', ['Körüklü cep', 'Kanguru cep', 'Torba cep'], 'Fileto cep giysinin içine yerleştirilir ve dışarıdan sade bir çizgi gibi görünür; resmî ceket ve pantolonlarda tercih edilir.'),
  ('Kumaş eni 150 cm\'dir. Bir etek parçasının kalıbı 75 cm genişliğinde ve 60 cm boyundadır; parçalar kumaşın enine yan yana yerleştirilebilmektedir. 10 parça kesmek için en az kaç metre kumaş gerekir?', '3', ['6', '1,5', '4,5'], 'Enine 150 / 75 = 2 parça sığar. 10 parça için 5 sıra gerekir; 5 × 0,6 m = 3 m kumaş yeterlidir.'),
  ('Bir dokuma tezgâhı dakikada 600 atkı atmaktadır. Dokunan kumaşta santimetrede 30 atkı ipliği bulunuyorsa tezgâh bir saatte kaç metre kumaş dokur?', '12', ['20', '1,2', '120'], 'Dakikada 600 / 30 = 20 cm kumaş dokunur. Bir saatte 20 × 60 = 1200 cm, yani 12 m.'),
  ('Bir kumaş topu 15 kilogram gelmektedir. Kumaşın eni 1,5 metre ve gramajı 200 g/m² olduğuna göre topta kaç metre kumaş vardır?', '50', ['75', '30', '100'], 'Toplam alan 15 000 g / 200 g/m² = 75 m²\'dir. Uzunluk = 75 / 1,5 = 50 m.'),
  ('Kadın siluetini biçimlendiren iç iskeletler tarihsel olarak eskiden yeniye doğru nasıl sıralanır?', 'Verdugado, panier, krinolin, tournure', ['Panier, verdugado, tournure, krinolin', 'Krinolin, verdugado, panier, tournure', 'Tournure, krinolin, panier, verdugado'], 'Verdugado 16., panier 18. yüzyıla aittir; krinolin 1850-60\'larda, tournure 1870-80\'lerde moda olmuştur.'),
  ('Aşağıdaki modacılar moda evlerini kurdukları ya da en etkili oldukları döneme göre eskiden yeniye doğru nasıl sıralanır?', 'Worth, Poiret, Dior, Quant', ['Poiret, Worth, Quant, Dior', 'Dior, Worth, Poiret, Quant', 'Quant, Dior, Poiret, Worth'], 'Worth 1850\'lerin sonunda, Poiret 1900\'lerde, Dior 1947\'de, Mary Quant 1960\'larda öne çıkmıştır.'),
  ('Etiketinde \'%100 pamuk\' yazan bir gömleğin kumaşından alınan iplik yakıldığında eriyip ucunda sert bir boncuk bırakıyor. Bu gözlemden çıkarılabilecek en doğru sonuç hangisidir?', 'Etiket yanıltıcıdır; kumaşta sentetik lif vardır', ['Gömlek organik pamuktan yapılmıştır', 'Pamuk merserize edildiği için erimiştir', 'Kumaş yüksek gramajlı olduğu için erimiştir'], 'Saf pamuk erimez, kâğıt gibi yanıp yumuşak kül bırakır; erime ve sert boncuk sentetik liflerin belirtisidir.'),
  ('Bir öğrenci \'Saten parlak bir kumaş olduğuna göre mutlaka ipekten yapılmıştır.\' diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Yanlıştır; saten bir örgü türüdür, polyester ya da pamuktan da dokunabilir', ['Doğrudur; saten yalnız ipek liflerinden dokunabilir', 'Doğrudur; parlak her kumaş ipek liflidir', 'Yanlıştır; saten yalnız yün liflerinden dokunur'], 'Satenin parlaklığı lif türünden değil örgü yapısından gelir; ipek saten, polyester saten ve pamuk saten (saten pamuklu) vardır.'),
  ('Bir dağcıya soğuk ve değişken havalarda \'üç katman\' giyinme ilkesi öneriliyor. Bu ilkeye göre katmanların içten dışa doğru en uygun sırası hangisidir?', 'Teri uzaklaştıran ince iç katman, sıcak tutan polar ara katman, rüzgâr ve su geçirmez dış kabuk', ['Kalın pamuklu iç katman, su geçirmez ara katman, polar dış katman', 'Su geçirmez iç katman, ince pamuklu ara katman, yün dış katman', 'Polar iç katman, pamuklu ara katman, kot dış katman'], 'İç katman nemi tenden uzaklaştırır, ara katman ısı yalıtımı sağlar, dış katman rüzgâr ve yağmuru keser. Pamuk nemi tuttuğu için iç katmanda önerilmez.'),
  ('Kuş tüyü montların teknik özelliklerinde belirtilen \'fill power\' (kabarıklık gücü) değeri neyi gösterir?', 'Belli ağırlıktaki tüyün ne kadar hacim kapladığını', ['Montun su geçirmezlik düzeyini', 'Tüylerin hangi kuştan alındığını', 'Montun kaç kez yıkanabileceğini'], 'Fill power yükseldikçe aynı ağırlıktaki tüy daha fazla hacim kaplar ve daha çok hava tutar; bu da daha hafif ama daha sıcak bir mont demektir.'),
  ('Etiketinde \'kaşmir hissi veren\' ifadesi bulunan yüzde yüz akrilik bir kazak için en doğru değerlendirme hangisidir?', 'Kazakta kaşmir yoktur; ifade yalnız tutumunun benzediğini anlatır', ['Kazak kaşmir keçisi yününden yapılmıştır', 'Kazak yarı yarıya kaşmir içerir', 'Akrilik kaşmirle aynı lifin farklı adıdır'], 'Lif içeriğini etiketteki yüzde bilgisi gösterir; \'hissi veren\' gibi ifadeler pazarlama dilidir ve gerçek lif içeriği anlamına gelmez.'),
  ('Hint achkan ceketinden esinlenen, hakim yakalı ve kalça boyunda ceket hangi devlet adamının adıyla anılır?', 'Jawaharlal Nehru', ['Mahatma Gandhi', 'Indira Gandhi', 'Muhammed Ali Cinnah'], 'Nehru\'nun sık giydiği bu ceket 1960\'larda Batı\'da da moda oldu; dönemin pop müzisyenleri tarafından benimsendi.'),
  ('Güney Asya\'da erkek ve kadınların giydiği, dize kadar uzanan ve yakası yırtmaçlı bol gömleğe ne ad verilir?', 'Kurta', ['Sari', 'Dhoti', 'Lehenga'], 'Kurta genellikle pamuklu kumaştan yapılır; pijama ya da şalvar benzeri pantolonlarla giyilir.'),
  ('Meksika ile özdeşleşen geniş kenarlı \'sombrero\' şapkasının adı İspanyolcada hangi anlama gelen sözcükten türemiştir?', 'Gölge', ['Güneş', 'Rüzgâr', 'Yağmur'], 'Sombrero İspanyolca \'sombra\' (gölge) sözcüğünden gelir; geniş kenarları yüzü ve omuzları güneşten korur.'),
  ('Sibirya\'ya kışın gidecek bir gezgine, kulaklıkları aşağı indirilip çene altında bağlanabilen kürk bir şapka öneriliyor. Bu şapkanın adı nedir?', 'Uşanka', ['Kalpak', 'Bere', 'Kasket'], 'Uşanka Rusçada \'kulaklı\' anlamına gelir; sert Rus kışında kulakları ve boynu korur.'),
  ('Japonya\'da kimononun üzerine giyilen, kalça ya da diz boyunda, önü bağcıkla tutturulan ceket türü hangisidir?', 'Haori', ['Obi', 'Tabi', 'Geta'], 'Haori kimononun üstüne resmiyet ve sıcaklık katmak için giyilir; önü kapatılmaz, iki bağcıkla bağlanır.'),
  ('Hollanda ile özdeşleşen, tek parça tahtadan oyulmuş geleneksel ayakkabıya Felemenkçede ne ad verilir?', 'Klompen', ['Galoş', 'Espadril', 'Mokasen'], 'Tahta ayakkabılar nemli ve çamurlu arazide ayağı kuru tuttuğu için çiftçiler arasında yüzyıllarca kullanıldı.'),
  ('Kuru ve çok soğuk bir Rus kışında köyde yaşayan birine tek parça keçeden yapılmış, dikişsiz kalın bir çizme öneriliyor. Bu çizmenin adı nedir?', 'Valenki', ['Klompen', 'Mokasen', 'Galoş'], 'Valenki yün keçeden kalıp üzerinde biçimlendirilir; kuru soğukta çok sıcak tutar, ıslak havada ise üzerine lastik galoş giyilir.'),
  ('Paris\'te haute couture koleksiyonları yılda kaç kez ve hangi aylarda gösterilir?', 'İki kez; ocak ve temmuz aylarında', ['Dört kez; her mevsim başında', 'Bir kez; yalnız eylül ayında', 'Üç kez; mart, haziran ve ekimde'], 'Haute couture ilkbahar-yaz koleksiyonları ocakta, sonbahar-kış koleksiyonları temmuzda Paris\'te sunulur.'),
  ('Bir giysinin ölçülerini, malzemelerini, dikiş ve aksesuar ayrıntılarını üreticiye eksiksiz anlatan teknik dosyaya ne ad verilir?', 'Teknik föy', ['Lookbook', 'Esin panosu', 'Defile programı'], 'Teknik föy üretici ile tasarımcı arasındaki ortak dildir; ölçü tabloları, teknik çizimler ve malzeme listesi içerir.'),
  ('Bir giyim markasının ürünlerini kendi fabrikası yerine sözleşmeyle başka bir atölye ya da fabrikaya ürettirmesine ne ad verilir?', 'Fason üretim', ['Haute couture', 'Kapsül üretim', 'El tezgâhı üretimi'], 'Fason üretimde marka tasarım ve satışı üstlenir, dikim ise anlaşmalı üreticide yapılır; hazır giyim sektöründe çok yaygındır.'),
  ('Bir müzede iki elbise sergileniyor: biri korse ve krinolinle giyilen geniş etekli bir elbise, öbürü düşük belli, düz ve diz boyunda bir elbise. Bu elbiseler hakkında hangisi doğrudur?', 'Düşük belli düz elbise daha yenidir; 1920\'lere aittir', ['Krinolinli elbise daha yenidir; 1920\'lere aittir', 'İkisi de aynı on yılda giyilmiştir', 'Düşük belli elbise 18. yüzyıla aittir'], 'Krinolin 1850-60\'larda moda olmuştur; düşük belli, korsesiz düz siluet ise 1920\'lerin tipik görünümüdür.'),
  ('Bir arkadaşınız \'Pamuklu bir tişört her koşulda sentetik bir tişörtten daha çevrecidir.\' diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Her koşulda doğru değildir; iki lifin de farklı çevresel yükleri vardır', ['Tümüyle doğrudur; pamuk hiçbir çevresel yük taşımaz', 'Tümüyle doğrudur; sentetik lifler hiç geri dönüştürülemez', 'Yanlıştır; sentetik lifler hiçbir çevresel sorun yaratmaz'], 'Pamuk tarımı çok su ve tarım ilacı gerektirebilir; sentetik lifler ise petrole dayanır ve mikroplastik salar. Karşılaştırma üretim, kullanım ve atık aşamalarının birlikte değerlendirilmesini gerektirir.'),
  ('Ekose desenli bir kumaştan ceket diken bir terzi, karelerin ön ortada ve yan dikişlerde birbirini tutmasını istiyor. Bunun için ne yapmalıdır?', 'Kalıpları desene göre eşleyerek yerleştirip daha fazla kumaş ayırmalıdır', ['Kalıpları kumaşa rastgele yerleştirip daha az kumaş kullanmalıdır', 'Parçaları verev keserek desenleri gizlemelidir', 'Dikişleri desenin üzerine biye ile kapatmalıdır'], 'Desen eşleştirmede kalıplar karelerin hizasına göre konur; bu nedenle düz kumaşa göre daha fazla kumaş harcanır.'),
  ('Kadife kumaştan ceket kesen bir terzi tüm kalıp parçalarını aynı yöne bakacak biçimde yerleştiriyor. Bunun nedeni nedir?', 'Havın yönü ışığı farklı yansıttığı için parçalarda ton farkı oluşmasını önlemek', ['Kadifenin yalnız bir yönde dikilebilmesi', 'Kumaşın enine hiç esnememesi', 'Kadifenin ters yüzünün daha parlak olması'], 'Havlı kumaşlarda tüylerin yatış yönü ışığın yansımasını değiştirir; ters yerleştirilen bir parça daha açık ya da koyu görünür.'),
  ('Bir fotoğrafta geniş vatkalı ceket, iri takılar ve yüksek kabarık saçlarla iş yerine giden bir kadın görülüyor. Bu görünüm en çok hangi on yılın modasını yansıtır?', '1980\'ler', ['1920\'ler', '1950\'ler', '1990\'lar'], 'Geniş omuzlu güç giyimi, iri aksesuarlar ve hacimli saçlar 1980\'lerin iş dünyasındaki kadın modasının tipik öğeleridir.'),
  ('1860\'larda geçen bir dönem filminde hangi kostüm ayrıntısı döneme aykırı (anakronik) olur?', 'Naylon çorap', ['Krinolinli etek', 'Balenli korse', 'İpek eldiven'], 'Naylon 1930\'ların sonunda geliştirilmiş ve 1940\'ta çorap olarak satışa sunulmuştur; krinolin, korse ve ipek eldiven 1860\'larda yaygındı.'),
  ('Bir reklamda \'%100 bambu tişört; tümüyle doğal bir bitki lifi\' deniyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Yanıltıcı olabilir; bambu kumaşların çoğu kimyasal işlemle viskon olarak üretilir', ['Tümüyle doğrudur; bambu pamuk gibi koza veren bir bitkidir', 'Tümüyle doğrudur; bambu lifi hiçbir işlem görmeden eğrilir', 'Yanlıştır; bambu kumaş petrolden üretilen bir sentetiktir'], 'Bambu tekstillerin büyük kısmı bambu selülozunun çözülüp yeniden lif hâline getirilmesiyle (viskon yöntemiyle) üretilir; bu nedenle \'doğal lif\' ifadesi yanıltıcı olabilir.'),
  ('Bir öğrenci \'Topuklu ayakkabı tarih boyunca yalnız kadınlara özgü bir giyim parçası olmuştur.\' diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Yanlıştır; 17. ve 18. yüzyıl Avrupa\'sında soylu erkekler de topuklu giyerdi', ['Doğrudur; erkekler hiçbir dönemde topuklu giymemiştir', 'Doğrudur; topuklu ayakkabı ilk kez 1950\'lerde çıkmıştır', 'Yanlıştır; topuklu ayakkabıyı yalnız askerler giyerdi'], 'XIV. Louis\'nin sarayında kırmızı topuklu ayakkabılar erkek soyluların ayrıcalığıydı; topuk ancak 18. yüzyılın sonunda erkek modasından çekildi.'),
  ('İpek ve yün giysilerin klorlu çamaşır suyuyla ağartılmaması neden önerilir?', 'Klor bu protein lifleri tahrip edip sararmaya yol açar', ['Klor bu lifleri anında boyar', 'Klor yalnız sentetik lifleri ağartabilir', 'Bu lifler suyla hiç temas etmemelidir'], 'İpek ve yün protein liflerdir; klor bu lifleri zayıflatır, sertleştirir ve sarartır. Bu nedenle etiketlerinde çoğunlukla çarpılı üçgen bulunur.'),
  ('Bir öğrenci \'Moda trendleri tümüyle rastlantısal ortaya çıkar; toplumsal olaylarla bir ilgisi yoktur.\' diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Yanlıştır; savaşlar, ekonomi ve teknoloji modayı doğrudan etkiler', ['Doğrudur; moda hiçbir dış etkene bağlı değildir', 'Doğrudur; trendleri yalnız hava durumu belirler', 'Yanlıştır; modayı yalnız yasalar belirler'], 'Savaş dönemi kumaş kısıtlamaları, sentetik liflerin icadı ya da kadınların iş hayatına girmesi gibi gelişmeler giyim biçimlerini doğrudan değiştirmiştir.'),
  ('Geleneksel balıkçı kazaklarının yünü bazen yıkanmadan, doğal yağı kısmen korunarak örülürdü. Bunun amacı neydi?', 'Yündeki doğal yağın kazağa su iticilik kazandırması', ['Kazağın daha parlak renkli olması', 'Yünün daha hızlı kuruması', 'Kazağın daha ince ve hafif olması'], 'Yündeki lanolin doğal bir su itici gibi davranır; yağı korunmuş yünden örülen kazaklar denizdeki rüzgâr ve serpintiye karşı daha iyi korurdu.'),
];
